@OptIn(ExperimentalJsExport::class)
@JsExport
fun loop() {
    try {
        runWithSourceMapSupport {
            PainAndGain.tick()
        }
    } catch (t: Throwable) {
        // страховка: даже если source-map-обработчик упадёт, логируем ошибку и не роняем тик
        println("loop error: ${t.message}")
        println(t.stackTraceToString())
    }
}

/**
 * Season 4 «Pain and Gain» (basic). Первая версия — до первого живого матча.
 *
 * Правила (описание арены в клиенте, 04.09.2026): у каждого игрока ЗАРАНЕЕ ВЫДАННАЯ армия из 14
 * крипов — ни спавна, ни стройки, ни энергии, ни замены погибшим. По карте семь нейтральных
 * [ScoreFlag]: крип захватывает флаг, ВСТАВ на его клетку; захваченный флаг каждый тик приносит
 * владельцу очки и вешает глобальный дебафф на ВСЮ его армию (флаги одного типа складываются):
 *
 *  | флаг              | шт | очки/тик | эффект                      | один  | два  |
 *  |-------------------|----|----------|-----------------------------|-------|------|
 *  | Vulnerability     | 1  | 5        | входящий боевой урон        | ×1.1  | —    |
 *  | Heal reduction    | 2  | 4        | лечение                     | ×0.75 | ×0.5 |
 *  | Attack reduction  | 2  | 3        | удар ATTACK                 | ×0.8  | ×0.6 |
 *  | Ranged reduction  | 2  | 3        | выстрел RANGED_ATTACK       | ×0.8  | ×0.6 |
 *
 * Итого 25 очков/тик (MAX_SCORE_PER_TICK). 2000 тиков; побеждает больший счёт, равный — ничья;
 * досрочно — уничтожение армии противника (победа независимо от счёта) или недосягаемый отрыв.
 *
 * Оси решения, все из состояния, не из подгонки под карту:
 *  - счёт: безоружные крипы — захватчики, идут по флагам по выигрышу очков за тик хода; армия
 *    берёт флаги по пути и рейдом. Флаг берётся, только если армия С ЕГО дебаффом не слабее
 *    армии врага (маргинальная цена по Ланчестеру с эффектами обеих сторон) — или если по
 *    прогнозу счёта мы проигрываем: тогда очки важнее силы;
 *  - бой: армия одной группой; постура — ДОБИТЬ (уничтожение армии врага выигрывает матч:
 *    перевес PUSH_RATIO по мощи с эффектами), РЕЙД/ЗАЧИСТКА флага, ПОСТ у своих флагов, ОТХОД
 *    (враг сильнее в RETREAT_RATIO и рядом — армию без замены не разменивают). Внутри — локальный
 *    перевес, цена боя в запасе хода, сплочение, бегство от смертельного урона, фокус, лечение;
 *  - мощь считается по МОДИФИЦИРОВАННЫМ эффектами урону, лечению и хитам (InfluenceMap).
 */
object PainAndGain {

    // ---------- боевые константы ----------
    private const val RANGED_RANGE = 3
    private const val HEAL_RANGE = 3
    private const val MELEE_KEEP_RANGE = 2
    private const val MELEE_KITE_DISCOUNT = 0.1
    /** ДОЛЯ СМЕЖНОСТИ МИЛИ В МОЩИ (v103, пункт 5 плана оператора — «цена стрелков»): модель считала удар мили целиком (четыре
     *  M8A8 — 960 в тик против 300 у пяти M6R6, три четверти урона стороны), а по реплеям 238/249 мили бьёт, только когда
     *  вплотную — у него 20 % крип-тиков боя, у нас 5–8 %: 36 % его урона и 19 % нашего пришлись на мили. Отсюда цена флагов
     *  наоборот: R3 (−20 % стрельбы) стоил модели 1 % мощи, A3 (−20 % удара) — 7,5 %, и скаут брал R3 первым в каждом матче,
     *  отдавая пятую часть того огня, которым бой решается (открыто с матча 47). В счёте мощи удар мили входит с долей
     *  MELEE_ADJACENCY_SHARE (его уровень; наш ниже, пока v101 не поднял), хиты мили — целиком: он принимает огонь (r->melee
     *  163 из его 361 выстрела). Ланчестер по-прежнему √(урон − лечение) × хиты. ОТВЕРГНУТО стендом (v103, поверх v102):
     *  гейт 131/131, но 27 хуже / 40 лучше — перетасовка всего; spread 6/6 → 2/6 (m31 11058:24336, m19 17111:24313, m28, m33),
     *  camp+shy 5/5 → 3/5 (m30 17998:22529, m31 23274:24031), brawl m32 — наша армия уничтожена (5219:14635). Цены флагов
     *  перевернулись (R3 из дешёвого стал дорогим), и все пороги паритета, настроенные под старые цены, стали запрещать захваты,
     *  на которых стоят гонки стенда. Цена стрелков в модели верна по реплеям, но её нельзя менять отдельно от порогов —
     *  открытая находка с числом: доля 0,25 требует перенастройки PARITY_FLOOR/CAPTURE_FLOOR по всем семьям. */
    private const val USE_MELEE_ADJACENCY_SHARE = false
    private const val MELEE_ADJACENCY_SHARE = 0.25
    /** ...И ТА ЖЕ ДОЛЯ, НО ИЗМЕРЕННАЯ, А НЕ НАЗНАЧЕННАЯ (v193). Находка выше открыта с матча 47 и закрыта не была:
     *  модель считает удар мили ПОЛНЫМ весом, поэтому назначает R3 (−20 % стрельбы) ценой в 1 % мощи, а A3 (−20 %
     *  удара) — в 7,5 %, и бот отдаёт пятую часть огня, которым бой решается, чтобы сберечь удар, которого нет.
     *  Замер по реплеям против Coldkimchi#2: мили стоит вплотную к врагу 1,1 % крипо-тиков контакта у нас и 2,3 % у
     *  него (в патовом матче 4,9 % и 0,5 %) — то есть дебафф A3 почти бесплатен ОБЕИМ сторонам, а R3 дорог обеим.
     *  Прежняя попытка (v103) была отвергнута стендом не по существу: она ставила КОНСТАНТУ 0,25, цены переворачивались
     *  во всех сценариях сразу, и пороги паритета, настроенные под старые цены, начинали запрещать захваты, на которых
     *  стоят гонки стенда. Измеряемая доля этого не делает: на стенде, где враг идёт в контакт, она сама поднимается
     *  к единице, до заполнения окна равна единице, и старое поведение остаётся ровно там, где мили действительно бьёт. */
    private const val USE_MEASURED_MELEE_SHARE = true
    /** Мили, не достающий врага, отряжается за флагами (v194, см. meleeIdle). Порогов своих не заводит: выпуск идёт
     *  ПРЕЖНЕЙ проверенной цепочкой с её паритетными полами, а те после v193 считают вклад мили по измеренной доле —
     *  то есть модель сама разрешает отпустить того, кто ничего не даёт, и сама запретит, когда он начнёт бить. */
    private const val USE_IDLE_MELEE_RUNS = true
    /** ОТВЕРГНУТО (v195, см. inFront в planFight): мили вставал позади стрелков, когда по замеру не достаёт. Правило
     *  почти не срабатывало — прибор `back` дал 2 тика за матч, — потому что против СОМКНУТОГО блока строй раздаёт
     *  planBlock, а не planFight. И посылка неверна: в planBlock мили стоит в общей линии со стрелками НАМЕРЕННО, и
     *  рядом записан замер, который это держит, — строй «стрелки впереди, мили позади» (v37) кайтер стенда разоружал
     *  первыми. Живые числа согласны: гибнут только атакующие части (0–16 из 32), стрелковые целы (24–30 из 30), то
     *  есть тела мили работают самой дешёвой бронёй, какая у нас есть. Убирать броню, которая всё равно ничего не
     *  бьёт, — значит подставить под тот же огонь единственное, чем мы бьём. */
    // СОГЛАСОВАННОСТЬ СТРОЯ жёсткими условиями (v200–v201) снята этапом 6: «мили в дальности лечения», «лекарь за
    // линией», «стрелок не впереди мили» и упреждение по уходящему были ЗАПРЕТАМИ там, где нужны предпочтения, и
    // запирали друг друга — стрелок выталкивался за собственную дальность выстрела. Теперь это слагаемые оценки
    // (см. scoreMelee/scoreRanged/scoreHeal), а замеры, которыми они обосновывались, перенесены в docs.
    private const val USE_MELEE_BEHIND_WHEN_IDLE = false
    /** РЯД ЦЕЛИТСЯ НА КЛЕТКУ БЛИЖЕ, КОГДА ОН УКЛОНЯЕТСЯ (v196). Ряд стрелков ставится в RANGED_RANGE от ближайшей
     *  угрозы — ровно в три, — но его блок меняет клетку 71–76 % тиков контакта, и шаг делается ОДНОВРЕМЕННО с нашим:
     *  ряд, нацеленный в три, приходит в четыре. Замер по консоли: медиана дистанции наших стрелков до ближайшего его
     *  крипа — 4 при дальности выстрела 3, в дальности они 41 % замеров, прибор `reach` даёт 1,5–2 из 5, а `conc` —
     *  1,3–1,8 из 5 при том, что трое его лекарей возвращают 216 хитов в тик и цель начинает терять хиты только под
     *  залпом ЧЕТЫРЁХ. Один шаг упреждения — и ряд приходит туда, откуда стреляют. Признак уклонения не назначен, а
     *  измерен той же долей касаний: против соперника, идущего в контакт, она равна единице и прицел прежний.
     *  ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ: правило срабатывает (прибор `lead` 19–139 за матч, первое за сутки правило с
     *  ненулевым счётчиком), но СВОЙ прибор не двигает — `reach` за окно боя 1,11 против 1,13 у сборки без него, `conc`
     *  1,48 против 1,48, — а исход 0:4 при трёх аннигиляциях. Объяснение, которое остаётся открытым: ряд, придвинутый
     *  на клетку, входит в его кольцо глубже, его залп сгоняет стрелков обратно, и средняя дистанция не меняется. */
    private const val USE_ROW_LEADS_KITER = false   // ОТВЕРГНУТО: см. числа ниже

    /** Перевес, при котором армия идёт добивать, и порог продолжения. Порог продолжения выше единицы: прежний
     *  0.9 вместе со входом «по контакту» открывал лазейку — контакт с ОДНИМ стрелком включал ДОБИТЬ, а дальше
     *  гистерезис держал его при 0.97, и армия прошла через всю карту к вражескому углу (матч 3, t=60–96). */
    private const val PUSH_RATIO = 1.3
    /** Наступление окупается: за окно STALL_TICKS с врага снято не меньше, чем с нас (суммы хитов живых, лечение обеих сторон
     *  внутри), иначе наступление снимается и строй собирается заново. Матч 44 (けろびー v1): к 180-му мы выигрывали
     *  16000/16000 против 12800/12800, трое его мили мертвы, и при перевесе 1.3 армия пошла в наступление — строй распущен,
     *  крипы гнались поодиночке за линией стрелков, которая отошла на 18 клеток, стреляя из трёх: 311 его выстрелов против
     *  наших 175 (68 % крип-тиков с выстрелом против 44 %), r→melee 137 по идущим первыми мили — за 60 тиков размен
     *  перевернулся, армия потеряна. Ланчестер даёт право наступать, размен говорит, окупается ли оно. */
    private const val PUSH_EXCHANGE = 1.0
    /** Перехват (v40): враг с боем рядом, чей огонь STALL_TICKS тиков подряд не снял с нас ни хита, — фермер (けろびー v5, матчи
     *  51 и 57: шесть флагов к 82-му, 1400 тиков рядом без выстрела, 8 в тик против 17). Его не догнать на равной скорости, и
     *  ему не нужно драться — но флаг он берёт, только встав на клетку флага, и идёт за ближайшим не своим: армия идёт ТУДА
     *  и стоит там — на своём флаге постом, на ничьём или его — захватом (гейты боя открыты только для этого флага; полное
     *  снятие гейтов — v39 — рассыпало армию по флагам до паритета с его полной армией и проиграло больше). Наступление на
     *  такого врага снято: наступление — это погоня. Так советуют и внешние разборы (jonwinsley: армия «между врагом и нашим
     *  флагом»; см. docs/pain-and-gain-research.md, §4). v42: снято, только пока есть что перехватывать (флаг не наш) или мы
     *  впереди по очкам — фермер, севший на всех флагах, не придёт никуда, и его надо бить (матч 70, см. chaseVeto). */
    private const val USE_INTERCEPT = true
    /** Отряды против фермера (v52; матчи 72, 87, 90, 101, 107 — семь проигрышей けろびー v5 по очкам при целых армиях): он
     *  ходит блобом по флагам и никогда не стреляет, а одна армия не может и гнать его, и стоять на пяти флагах — он держит
     *  4–5, мы 2–3, 13098:23022. Сигнал фермера — тот же, что у перехвата, но выдержанный: враг рядом PASSIVE_TICKS тиков и не
     *  снял с нас ни хита (боец так не делает). Тогда слабейшие вооружённые уходят в БЕГУНЫ — по одному на каждый флаг, на
     *  котором не стоит наш, — пока ядро армии не слабее его по паритету; бегуны берут и держат флаги логикой скаутов
     *  (паросочетание по ценности, бегство от охотника) и стреляют по тому, что в дальности. Распускаются в тот тик, когда он
     *  выстрелит. Первая форма (v44b, набор по запасу наступления, без сигнала фермера) отвергнута: 121 строка хуже — отряды
     *  уходили в карту во время боя и построения. ВЫКЛЮЧЕНО после двух замеров сигнала: по noFireTicks ≥ PASSIVE_TICKS (v52)
     *  гейт чист и farm m21/m25/m33/m34 зеленеют, но живьём (матч 108, 1800 тиков) не включилось ни разу — счётчик сбрасывался,
     *  когда блоб отходил дальше NEAR_RANGE; по «сто тиков без хита с последней досягаемости» (v52b) включается и против сидящего
     *  лагерем — три гейтовые строки красные (farm+weak m32 4502:18848, camp m29/m30): ядро без трёх крипов идёт на его блоб и не
     *  добивает. ВКЛЮЧЕНО (v56) с третьим признаком — движением блоба (центр его вооружённых за 50 тиков сместился на 10) — и
     *  ОТВЕРГНУТ в первой же живой серии (матч 126, десятый проигрыш фермеру 15389:23231): 46 строк detach, отряды по 2–4
     *  распускались через 1–45 тиков с moved=false — его блоб паркуется на флаге на две сотни тиков (по реплею центр за 50 тиков
     *  сдвигался меньше 10 клеток в 63 % тиков, самая длинная пауза 209; в матче 119 — 26 %) и уходит, когда мы подходим.
     *  v57: признак — ПОГОНЯ БЕЗ СБЛИЖЕНИЯ (та же мера, что у третьей сетки простоя, см. USE_KEEPS_DISTANCE_STALL: в добивании
     *  дистанция между центрами за CHASE_WINDOW не сократилась и он дальше броска), наблюдавшаяся не дальше PASSIVE_TICKS назад;
     *  собранный отряд держится, пока он не ударит по нам. Лагерь при толчке сближается — отрядов нет, ядро добивает его (стенд
     *  camp); кайтер и фермер держат дистанцию — отряды идут за флагами. «Держит дистанцию» — это ОН уходит: центр его
     *  вооружённых за окно сместился не меньше чем на CHASE_WINDOW / 2, иначе стоячий лагерь, у которого мы сами замираем в
     *  10–13 клетках (мигание матча 70), давал отряд (стенд m31 camp: 2 отряжённых на 498-м). Набор — от слабейших, как в v52:
     *  мили первыми (в одиночку убивает и лекаря, 240 против 72) ОТВЕРГНУТО стендом — m28 kite 4970:23907, армия стёрта к
     *  500-му: отряд из мили отозван по первому удару и вернулся по одному под огонь кайтера, шесть смертей за 70 тиков у D5
     *  (в v56 та же строка — «стёрт на 346-м»). Мили-бегун, если он всё же в отряде, бьёт вплотную (healAndShoot за бегунов
     *  только стрелял). Флаг с одиночным врагом слабее бегуна — цель, а не стена; «стая дойдёт раньше» для вооружённого бегуна —
     *  по силе, не по факту. Срок «досягаемость не дальше ста тиков назад» снят ещё в v56: он и был причиной «не включилось
     *  ни разу». */
    private const val USE_DETACH = true
    private var USE_POST_INSIDE = false
    /** ПОСТ БЕЗ СВОИХ ФЛАГОВ — БЛИЖАЙШИЙ ФЛАГ НАШЕЙ ПОЛОВИНЫ, НЕ ДОМ (v88, завершение пункта 1 решения оператора): матч 221
