    /** Число из константы арены (внешнее объявление может оказаться undefined — тогда запасное). */
    private fun num(v: dynamic, fallback: Double): Double = if (jsTypeOf(v) == "number") v.unsafeCast<Double>() else fallback

    private fun probe(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>, home: Position, enemyHome: Position) {
        println(
            "hello season4 pain-and-gain $BOT_VERSION: ${arenaInfo.season} - ${arenaInfo.name} level=${arenaInfo.level} " +
                "ticksLimit=${arenaInfo.ticksLimit} cpu=${arenaInfo.cpuTimeLimit}/${arenaInfo.cpuTimeLimitFirstTick}"
        )
        // подпись сборки: по ней видно, какая версия играет, даже если строку версии забыли поднять
        println(
            "tuning: pushX=$PUSH_EXCHANGE parity=$PARITY_FLOOR/$CAPTURE_FLOOR/$PARITY_FLOOR_STALLED push=$PUSH_RATIO/$PUSH_RATIO_BEHIND " +
                "stall=$STALL_TICKS/$STALL_PICKET/$STALL_DAMAGE/$STALL_COOLDOWN march=$MARCH_STALL_TICKS rush=$APPROACH_RUSH/$EVADE_EQUAL_RATIO " +
                "mass=$MASS_RANGE leash=$LEASH_RANGE meleeHold=$MELEE_HOLD_RANGE press=$PRESS_RANGE/$PRESS_PACK/$PRESS_PATIENCE/$PRESS_CLOSING/$PRESS_GIVEUP healer=$HEALER_VALUE keep=$KEEP_RANGE/$KEEP_PICKET/$KEEP_RELEASE"
        )
        println(
            "pain-and-gain: TICKS_LIMIT=${num(TICKS_LIMIT.asDynamic(), -1.0)} MAX_SCORE_PER_TICK=${num(MAX_SCORE_PER_TICK.asDynamic(), -1.0)} " +
                "FLAG_TYPES=${try { JSON.stringify(FLAG_TYPES) } catch (t: Throwable) { "?" }} " +
                "EFF: attack=$EFF_ATTACK_MODIFIER ranged=$EFF_RANGED_ATTACK_MODIFIER heal=$EFF_HEAL_MODIFIER taken=$EFF_DAMAGE_TAKEN_MODIFIER " +
                "power: R=$RANGED_ATTACK_POWER A=$ATTACK_POWER H=$HEAL_POWER/$RANGED_HEAL_POWER"
        )
        println("flags: " + flags.joinToString(" ") { "(${it.pos.x},${it.pos.y})${typeChar(it.type)}${it.score}my=${it.mine}" })
        println("home=(${home.x},${home.y}) enemyHome=(${enemyHome.x},${enemyHome.y})")
        println("my creeps (${myCreeps.size}): " + myCreeps.joinToString(" ") { "${it.id}(${it.x},${it.y})${bodySummary(it)}${if (it.spawning) "S" else ""}" })
        println("enemy creeps (${enemyCreeps.size}): " + enemyCreeps.joinToString(" ") { "${it.id}(${it.x},${it.y})${bodySummary(it)}" })
        val walls = getObjectsByPrototype(StructureWall::class).size
        val ramparts = getObjectsByPrototype(StructureRampart::class).size
        val spawns = getObjectsByPrototype(StructureSpawn::class).size
        println("structures: walls=$walls ramparts=$ramparts spawns=$spawns")
        // тела целиком (с порядком частей) — по ним видно, что выдано, и что умрёт первым
        for (c in myCreeps) println("body ${c.id}: " + c.body.joinToString("") { partChar(it.type).toString() })
        for (c in enemyCreeps) println("enemy body ${c.id}: " + c.body.joinToString("") { partChar(it.type).toString() })
    }

    private fun partChar(type: BodyPartType): Char = when (type) {
        TOUGH -> 'T'; MOVE -> 'M'; RANGED_ATTACK -> 'R'; ATTACK -> 'A'; HEAL -> 'H'; CARRY -> 'C'; WORK -> 'W'
    }

    private fun typeChar(type: String): Char = when (type) {
        EFF_ATTACK_MODIFIER -> 'A'
        EFF_RANGED_ATTACK_MODIFIER -> 'R'
        EFF_HEAL_MODIFIER -> 'H'
        EFF_DAMAGE_TAKEN_MODIFIER -> 'D'
        else -> '?'
    }

    private fun flagsSummary(flags: List<FlagInfo>): String =
        flags.joinToString(",") { "${typeChar(it.type)}${it.score}${if (it.ours) "+" else if (it.theirs) "-" else "0"}${if (it.occupant != null) (if (it.occupant.my) "s" else "e") else ""}${if (it.guards.isNotEmpty()) "g${it.guards.size}" else ""}" }

    /** Состав армий (живые части) — при каждом изменении: видно потери и покалеченных. */
    private fun logBodies(myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        if (!DEBUG_LOG) return
        val key = myCreeps.joinToString(",") { bodySummary(it) } + "|" + enemyCreeps.joinToString(",") { bodySummary(it) }
        if (key == lastBodiesKey) return
        lastBodiesKey = key
        println("armies t=${getTicks()}: ours(${myCreeps.size}) " + myCreeps.joinToString(" ") { "${bodySummary(it)}h=${it.hits}" } +
            " | enemy(${enemyCreeps.size}) " + enemyCreeps.joinToString(" ") { "(${it.x},${it.y})${bodySummary(it)}h=${it.hits}" })
    }

    // ==================== флаги и эффекты ====================

    private fun collectFlags(myCreeps: List<Creep>, enemyCreeps: List<Creep>, combatEnemies: List<Creep>): List<FlagInfo> {
        val result = ArrayList<FlagInfo>()
        val all = getObjectsByPrototype(ScoreFlag::class).filter { it.exists }
        for (f in all) {
            val occupant = (myCreeps + enemyCreeps).firstOrNull { !it.spawning && it.x == f.x && it.y == f.y }
            val guards = combatEnemies.filter { getRange(it, f) <= FLAG_GUARD_RANGE }
            result.add(FlagInfo(f, f.my, f.effectType, f.scorePerTick, occupant, guards))
        }
        // журнал захватов: смена владельца и кто стоит на клетке — проверка механики «встал — захватил»
        for (fi in result) {
            val owner = if (fi.ours) 1 else if (fi.theirs) -1 else 0
            val prev = lastFlagOwner[fi.id]
            if (prev != null && prev != owner && DEBUG_LOG) {
                println("flag t=${getTicks()}: (${fi.pos.x},${fi.pos.y})${typeChar(fi.type)}${fi.score} owner ${ownerName(prev)} -> ${ownerName(owner)} occupant=${fi.occupant?.let { "${if (it.my) "my" else "enemy"} ${bodySummary(it)}" } ?: "none"}")
            }
            lastFlagOwner[fi.id] = owner
        }
        return result
    }

    private fun ownerName(code: Int) = when (code) { 1 -> "us"; -1 -> "enemy"; else -> "none" }

    /** Множитель стека по таблице арены: удар/стрельба 0.8 → 0.6, лечение 0.75 → 0.5, входящий 1.1 (флаг один);
     *  дальше — тем же шагом (в матче сверяется с effects крипов). */
    private fun stackMul(type: String, count: Int): Double {
        if (count <= 0) return 1.0
        return when (type) {
            EFF_ATTACK_MODIFIER, EFF_RANGED_ATTACK_MODIFIER -> 1.0 - 0.2 * count
            EFF_HEAL_MODIFIER -> 1.0 - 0.25 * count
            EFF_DAMAGE_TAKEN_MODIFIER -> 1.0 + 0.1 * count
            else -> 1.0
        }.coerceAtLeast(0.0)
    }

    private fun sideModsOf(flags: List<FlagInfo>, mine: Boolean): InfluenceMap.SideMods {
        fun n(type: String) = flags.count { it.mine == mine && it.type == type }
        return InfluenceMap.SideMods(
            attack = stackMul(EFF_ATTACK_MODIFIER, n(EFF_ATTACK_MODIFIER)),
            ranged = stackMul(EFF_RANGED_ATTACK_MODIFIER, n(EFF_RANGED_ATTACK_MODIFIER)),
            heal = stackMul(EFF_HEAL_MODIFIER, n(EFF_HEAL_MODIFIER)),
            taken = stackMul(EFF_DAMAGE_TAKEN_MODIFIER, n(EFF_DAMAGE_TAKEN_MODIFIER)),
        )
    }

    /** Эффекты сторон: по массиву effects крипов, если API его отдаёт, иначе по подсчёту флагов (таблица
     *  арены). Печатает то и другое при изменении — в матче они обязаны совпасть. */
    private fun applyEffects(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        val ours = sideModsOf(flags, true)
        val theirs = sideModsOf(flags, false)
        InfluenceMap.setSideMods(ours, theirs)
        val sample = myCreeps.firstOrNull { InfluenceMap.hasEffectsApi(it) }
        InfluenceMap.setOurTaken(if (sample != null) InfluenceMap.takenOf(sample) else ours.taken)
        val enemySample = enemyCreeps.firstOrNull { InfluenceMap.hasEffectsApi(it) }
        InfluenceMap.setTheirTaken(if (enemySample != null) InfluenceMap.takenOf(enemySample) else theirs.taken)
        if (DEBUG_LOG) {
            val key = "$ours|$theirs|${sample?.let { JSON.stringify(it.effects) }}|${enemySample?.let { JSON.stringify(it.effects) }}"
            if (key != lastEffectsKey) {
                lastEffectsKey = key
                println("effects t=${getTicks()}: byFlags ours=[$ours] theirs=[$theirs] api ours=${sample?.let { JSON.stringify(it.effects) } ?: "n/a"} theirs=${enemySample?.let { JSON.stringify(it.effects) } ?: "n/a"}")
            }
        }
    }

    private fun accountScore(flags: List<FlagInfo>) {
        val cap = num(MAX_SCORE_PER_TICK.asDynamic(), Double.MAX_VALUE)
        ourRate = minOf(cap, flags.filter { it.ours }.sumOf { it.score }.toDouble()).toInt()
        enemyRate = minOf(cap, flags.filter { it.theirs }.sumOf { it.score }.toDouble()).toInt()
        ourScore += ourRate
        enemyScore += enemyRate
        val remaining = maxOf(0, arenaInfo.ticksLimit - getTicks())
        behindOnScore = ourScore + ourRate * remaining < enemyScore + enemyRate * remaining
        behindTicks = if (behindOnScore) behindTicks + 1 else 0
        // СНИМОК ДЕБЮТА (v216): по собственному замеру файла забег решается в первые двести тиков, а все приборы
        // в доках сняты «по последнему тику матча». Две строки, которые называют забег там, где он решается
        if (getTicks() == 100) race100 = "$ourRate:$enemyRate"
        if (getTicks() == 200) race200 = "$ourRate:$enemyRate"
        if (DEBUG_LOG && getTicks() % 100 == 0) println("score t=${getTicks()}: our=${ourScore.toInt()} (+$ourRate/t) enemy=${enemyScore.toInt()} (+$enemyRate/t) behind=$behindOnScore lead=${(ourScore - enemyScore).toInt()} maxSwing=${(cap * remaining).toInt()}")
    }

    /**
     * Брать ли этот (не наш) флаг сейчас. Свой — да. Врага в поле нет — да. Иначе — по паритету (см. PARITY_FLOOR):
     * армия С ЭТИМ дебаффом не слабее армии врага (CAPTURE_FLOOR), а пока отрыва нет — не меньше PARITY_FLOOR их
     * мощи:
     * маргинальная цена по Ланчестеру с эффектами ОБЕИХ сторон — у флага стрельбы дешевеет только стрелковая
     * часть урона, у флага лечения растёт чистый урон врага по нам, у флага уязвимости тают хиты, а чужой флаг
     * ещё и возвращает врагу то, что снимал с него. Отставание по счёту флагов больше не открывает: оно
     * значит, что враг держит больше и слабее — ответ ему бой (PUSH_RATIO_BEHIND), а не ещё один дебафф
     * (матч 3: «отстаём» на 2 очка при 6:10 разрешило всё подряд). Исключение — последние LAST_CALL_TICKS:
     * бой уже не успеет, и очки решают.
     */
    /** ⚠️ Параметр `runner` снят в v216: он был объявлен у обеих функций и НИ РАЗУ не читался в теле
     *  `captureBlock`. `runRunners` передавал `runner = true`, и это не меняло ничего — у бегуна те же ворота, что
     *  у армии. Дифф отчёта по 135 сценариям пуст побайтово, как и обязан быть у мёртвого. */
    private fun captureAllowed(ctx: Ctx, f: FlagInfo): Boolean = captureBlock(ctx, f) == null

    /** Какие ворота держат захват — null, если разрешено (v135, прибор к разрезу `tools/flagcut.py`): пять ворот отказывали
     *  молча, и в логе стояло только POISED, поэтому нельзя было сказать, ЧТО именно держит бегуна в клетке от свободного
     *  флага. Условия и их порядок те же, что были в captureAllowed. */
    private fun captureBlock(ctx: Ctx, f: FlagInfo): String? {
        if (f.ours) return null
        if (capTick != getTicks()) { capTick = getTicks(); capSeen.clear() }
        if (f.id !in capSeen) capOffered++
        if (ctx.combatEnemies.isEmpty()) return null
        // седьмой флаг — никогда при живой его армии (v127, USE_NO_SEVENTH_FLAG): все дебаффы наши, ни одного его
        if (USE_NO_SEVENTH_FLAG && ctx.flags.count { it.ours } + 1 >= ctx.flags.size) return "seventh"
        // последний зов и при РАВНОМ счёте: ничья 0:0 после уклонения (см. EVADE_EQUAL_RATIO) отдана не будет
        val ticksLeft = arenaInfo.ticksLimit - getTicks()
        val losingAtTheEnd = if (USE_LAST_CALL_PROJECTED) (ourScore - enemyScore) + (ourRate - enemyRate) * ticksLeft <= 0 else ourScore <= enemyScore
        if ((behindOnScore || losingAtTheEnd) && ticksLeft <= LAST_CALL_TICKS) return null
        // во время броска безфлаговой армии (см. unflaggedRushNow — тот же сигнал, что уводит армию в уклонение) флаг не берёт
        // НИКТО: бой через двадцать тиков, и дебафф ложится на него. Скаут брал R3 на 42–43-м тике во всех четырёх боях с
        // けろびー (матчи 38, 43, 44, 45) — −20 % стрелкам в решающем размене, — проходя порог паритета с запасом три очка мощи
        // (3967 против 3964: модель мощи считает мили полными, а их обезоруживают за первые двадцать тиков). Три очка в тик
        // за тридцать тиков против пятой части огня на весь бой
        // флаг перехвата (см. USE_INTERCEPT) открыт и в контакте с фермером, и при «бое близко»; остальные — нет
        val intercept = enemyNotFightingNow && f.id == interceptFlagId
        // «бой близко» закрывает НОВУЮ цель сразу, а УЖЕ выбранную снимает, лишь продержавшись RUSH_VETO_TICKS подряд (v114, матч
        // 277): его блоб, шагающий на 9–13 клетках, гонял темп подхода 31–63 % через порог 50 % каждые три тика, и цель D5 (ценность
        // 22–41) назначалась и снималась через тик — FLAG↔HOLD 17 раз за сто тиков, три шага к флагу и три назад, 520 тихих тиков
        // при отставании. Первый срез (вето целиком после 10 тиков) открывал флаги и настоящему броску — его темп тоже рвётся
        // (колонна растягивается): scatter m28 24317:18115 → 24316:24069, screen m32 −9515, army m35 из стирания в отрыв; при
        // вето только на новую цель бросок закрыт как прежде, а мигание не сбрасывает уже идущий захват
        // ...и та форма (v114b: вето сразу на новую цель, на уже идущую — после 10 тиков) тоже отвергнута: удержанная цель вела
        // армию к флагу навстречу НАСТОЯЩЕМУ броску — scatter m28 и screen m32 те же, camp m31 22868:22895 красный. Мера «он ходит,
        // а не бросается» в боте уже есть — простой «держит дистанцию» (окно DETACH_WINDOW, срабатывал в 277 на 221-м: «флаги до
        // 521» — и в этом окне цель мигала): простой снимает вето «бой близко», как снимает вето «в контакте» ниже
        // (USE_STALL_LIFTS_RUSH_VETO); настоящий бросок дистанцию сокращает и простоя не даёт
        // ⚠️ Здесь стояла `val current = f.id == objectiveFlagId` — объявлена и не читалась ни разу (остаток
        // отвергнутой липкости v114b). Снята в v215; дифф отчёта пуст побайтово, как и обязан быть у мёртвого
        // бегун берёт флаг НАШЕЙ половины и под броском (v128, USE_RUNNER_HALF_UNDER_RUSH): вето «бой близко» держало и скаутов —
        // матчи 5, 8, 19 серий 367–406: rush=true с 10-го по 39-й, бегуны 0 detached, наш первый флаг на 42–98-м при его шести к
        // 80–91-му; пол паритета ниже по-прежнему считает цену дебаффа
        // ...и у вето подхода есть СРОК (v215, см. USE_RUSH_VETO_EXPIRES). Доктрина безфлагового дебюта
        // (`unflaggedRushNow`) сроку не подлежит и остаётся глобальной
        val rushStale = USE_RUSH_VETO_EXPIRES && !unflaggedRushNow && fightImminentTicks > rushStartDist
        if (fightImminentNow && !rushStale && !intercept && !(USE_STALL_LIFTS_RUSH_VETO && stalledNow)) {
            // пара к погоне за кайтером (v221, см. kiteChaseSeen): сколько отказов доктрины безфлагового броска
            // выдано, пока мы гонимся за отходящим, который бьёт нас сильнее, чем мы его
            if (unflaggedRushNow) { kvetoAll++; if (kiteChaseSeen) kvetoHit++ }
            return capCount(f, if (unflaggedRushNow) "rush.unflagged" else "rush.approach")
        }
        if (fightImminentNow && rushStale) capCount(f, "rush.approach.expired")
        // в контакте флаги не берём, пока есть кому драться: дебафф ложится на идущий бой (матч 9: скаут взял R3 на 125-м
        // тике — −20% стрелкам в решающем размене ради трёх очков в тик); без стрелков защищать нечего, а очки — всё,
        // что осталось (стенд m4 sleeper: запрет при охоте за обломками отдал матч по очкам)
        // при бесплодной охоте (см. STALL_TICKS) контакт мнимый — висящие в трёх-шести клетках крипы россыпи мигали
        // контактом, и цель-флаг пропадала через тик после назначения (стенд m19 spread)
        // ...и ВЕТО КОНТАКТА СНИМАЕТСЯ, КОГДА МЫ ОТСТАЁМ ПО СКОРОСТИ ОЧКОВ (v180). Разбор семи поражений серии: пять из
        // них — не бой, а гонка, где обе армии целы, а мы держим ТРИ флага против его четырёх и набираем 10-12 очков в
        // тик против его 13-15. Вето контакта не давало взять четвёртый почти весь матч, а снималось лишь за
        // LAST_CALL_TICKS до конца — то есть после того, как отрыв уже сделан. Паритет мощи при этом остаётся: доктрина
        // не в том, чтобы не брать флаги, а в том, чтобы не брать их ценой армии
        // ...и снятие вето стоит АРМИИ, если брать флаг под его ударом без запаса: серия v180 дала 12-8 с рейтингом
        // +16, гонок-поражений стало три вместо пяти, но разгромов пять вместо двух — армия гибла к 200-300 тику.
        // Поэтому вето снимается только при ПЕРЕВЕСЕ, а не при простом паритете (v181)
        // ...и ЦЕЛАЯ АРМИЯ САМА ПО СЕБЕ ЕСТЬ ЗАПАС (v187, разбор Coldkimchi#2). Вето существует ради одного — не терять
        // армию за флаги; когда армия цела, оно защищает уже не её, а нулевой счёт. Против Coldkimchi#2 наша мощь
        // структурно ниже его (лечение блока перекрывает наш урон, потому Ланчестер и даёт нам около нуля), поэтому
        // порог CAPTURE_EDGE не берётся НИКОГДА, и матч кончается «обе армии целы, флаги 1:4, счёт 3 210:18 145».
        // Условие здесь не про мощь, а про потери: пока армия почти не тронута и мы отстаём по скорости очков, флаг
        // берётся. Дебафф флага ложится на владельца — эту цену считает паритетный пол ниже, он остаётся на месте
        val losingRace = USE_CAPTURE_WHEN_LOSING && behindOnScore && enemyRate > ourRate &&
            (!USE_CAPTURE_NEEDS_EDGE ||
                ourPowerOf(ctx.army, ctx.combatEnemies) >= enemyPowerOf(ctx.combatEnemies, ctx.army) * CAPTURE_EDGE)
        // ...и ПАТ СНИМАЕТ ВЕТО КОНТАКТА (v189): бой, в котором за целое окно ни одна сторона не потеряла заметной
        // доли хитов, армии не угрожает, а дебафф флага в нём ничего не решает — решают очки (см. stalemateNow)
        // ВЕТО КОНТАКТА — ПО МАССЕ АРМИИ, А НЕ ПО ЛЮБОМУ КРИПУ (v214, решение оператора: вето становится местным).
        // Контакт определялся в файле дважды: в runArmy по МАССЕ (см. massArmy), а здесь — по любому нашему
        // вооружённому на полной скорости. Одного отбившегося крипа, задетого его пикетом на другом конце карты,
        // хватало, чтобы закрыть разом ВСЕ семь флагов. Живой замер по 12 матчам: `contact` — 512 отказов в
        // поражениях против 99 в победах, то есть главный дискриминатор исхода.
        // ⚠️ Это НЕ отвергнутая правка про `enemyNear` (см. комментарий там же): та меняла постуру, из-за чего
        // висящий у хранителя враг переставал отменять цель-флаг, и m20 spread перешёл из победы в поражение.
        // Здесь меняется потребитель — гейт захвата, — а постура не трогается вовсе.
        val foes = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }
        val mass = centroidOf(ctx.army)
        val contactArmy = if (!USE_CONTACT_BY_MASS || mass == null) ctx.army else ctx.army.filter { getRange(it, mass) <= MASS_RANGE }
        if (!losingRace && !stalledNow && !intercept && contactArmy.any { fullSpeed(it) && hasWeapon(it) } && inContact(foes, contactArmy)) {
            // пара к вето контакта по размену (v221, только прибор): сколько отказов выдано контактом, в котором за
            // окно ни одна сторона не потеряла STALL_DAMAGE. Окно — прошлого тика: runRunners идёт раньше runArmy
            warmCapAll++; if (!exchangeLiveNow) warmCap++
            return capCount(f, "contact.mass")
        }
        // ...и отдельно считаем то, что этой правкой снято: стычка одиночки вне массы
        if (!losingRace && !stalledNow && !intercept && ctx.army.any { fullSpeed(it) && hasWeapon(it) } && inContact(foes, ctx.army))
            capCount(f, "contact.edge.lifted")
        // паритет (см. PARITY_FLOOR): не впереди или отрыв не растёт — флаг, оставляющий не меньше PARITY_FLOOR их
        // мощи; впереди с растущим отрывом — только не слабее
        // СИЛА ВРАГА ДЛЯ ЭТОГО ФЛАГА (v214, решение оператора: вето становится местным). Здесь стояло
        // `powerAfter(ctx, f)`, где сторона врага — ВСЯ его армия без учёта расстояния: крип в шестидесяти клетках
        // весил столько же, сколько стоящий вплотную. Дебафф флага глобален, поэтому его цену платит тот бой,
        // который РЕАЛЬНО случится, — это либо идущий бой (fightPack, «кто успевает прийти к нашей массе»), либо
        // бой за сам флаг (его боевые в FLAG_GUARD_RANGE, уже посчитаны в collectFlags как guards).
        // Кто не участвует ни в одном, не платит и не считается. Доктрина паритета остаётся: powerAfterFor
        // по-прежнему берёт нашу мощь С дебаффом флага против его без дебаффа и требует пол.
        // Взято дешёвое множество (guards вместо packAt): оно не стоит ни одного BFS. Если прибор capopp покажет,
        // что локализация мало что меняет, следующим шагом сюда войдёт packAt с полем пути к флагу.
        // ...и ПУСТО ЗНАЧИТ ПУСТО (v216, см. USE_EMPTY_OPP_MEANS_FREE): откат `.ifEmpty { ctx.combatEnemies }`
        // выключал локализацию ровно там, где она нужнее всего, — боя нет и флаг не охраняется
        val oppLocal = ctx.combatEnemies.filter { it.id in fightPackIds || f.guards.any { g -> g.id == it.id } }
        val opp = if (!USE_LOCAL_PARITY) ctx.combatEnemies
            else if (USE_EMPTY_OPP_MEANS_FREE) oppLocal else oppLocal.ifEmpty { ctx.combatEnemies }
        capOppSum += opp.size
        capAllSum += ctx.combatEnemies.size
        val (ours, theirs) = powerAfterFor(ctx,
            if (USE_CAPTURE_MEASURES_CORE) ctx.army else ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) },
            opp, f)
        // ИНВЕРСИЯ СНЯТА (v214). Здесь стояло `needed = ourScore <= enemyScore || ourRate <= enemyRate`, и когда
        // мы ВЕДЁМ по счёту и по темпу, пол становился CAPTURE_FLOOR = 1.0 — СТРОЖЕ, чем PARITY_FLOOR = 0.97 при
        // отставании. То есть выигранная позиция запрещала закреплять выигрыш. Замер по 12 живым матчам говорит,
        // что решают именно такие матчи: три поражения при ЖИВОЙ армии с разрывом 603, 1628 и 292 очка из ~18 000,
        // и одна победа с разрывом 168 — это 60–100 тиков ОДНОГО флага. Доктрина паритета остаётся: пол по-прежнему
        // сравнивает нашу мощь С дебаффом флага против его без дебаффа, просто перестаёт ужесточаться от того,
        // что мы впереди.
        // неподвижный враг — тоже армия: «пассивный» порог 0.95 пустил третий флаг против спящего, тот проснулся, и бой
        // при 0.96 был проигран (стенд m6 sleeper); порог один
        // проигранная гонка с тем, кто ни разу не ударил (v63, см. PARITY_FLOOR_LOST)
        val lostRace = lostRaceNow()
        val floor = if (lostRace) PARITY_FLOOR_LOST else if (stalledNow) PARITY_FLOOR_STALLED else PARITY_FLOOR
        // ПАРА К КЛАПАНУ (v218, см. lostRaceOpened): «послабление решило исход» — флаг прошёл по PARITY_FLOOR_LOST
        // и НЕ прошёл бы по PARITY_FLOOR. Считается ЗДЕСЬ, а не у признака, потому что вопрос прибора не «был ли
        // признак истинен», а «изменил ли он хоть один отказ»
        if (lostRace) {
            lostRaceOffers++
            if (ours >= theirs * floor && ours < theirs * PARITY_FLOOR) lostRaceOpened++
        }
        // ...и в ПАТУ паритетный пол тоже молчит: он сравнивает мощь, а в бою, где никто никого не убивает, мощь
        // обеих сторон ланчестером считается около нуля, и сравнивать нечего (v189)
        if (ours >= theirs * floor) return null
        // ФЛАГОВ БОЛЬШЕ ЦЕНОЙ НЕБОЛЬШОГО МИНУСА (v222, решение оператора, см. USE_FLAG_MAJORITY): армии СЕЙЧАС на паритете,
        // перевеса по флагам у нас нет, а этот флаг его даёт — минус ровно дебафф этого флага
        run {
            val side = if (USE_CAPTURE_MEASURES_CORE) ctx.army else ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }
            val oursNow = ourPowerOf(side, opp)
            val theirsNow = enemyPowerOf(opp, side)
            if (oursNow >= theirsNow * floor) {
                majOffers++
                val ourFlags = ctx.flags.count { it.ours }
                val hisFlags = ctx.flags.count { it.theirs }
                val ourAfter = ourFlags + 1
                val hisAfter = hisFlags - (if (f.theirs) 1 else 0)
                if (ourFlags <= hisFlags && ourAfter > hisAfter) {
                    majOpened++
                    if (USE_FLAG_MAJORITY) return null
                }
            }
        }
        capCount(f, "parity")
        return "parity(${ours.toInt()}/${(theirs * floor).toInt()})"
    }

    /** Считает отказ один раз на пару «тик × флаг» и возвращает причину как есть. */
    private fun capCount(f: FlagInfo, why: String): String {
        if (capTick != getTicks()) { capTick = getTicks(); capSeen.clear() }
        if (capSeen.add(f.id)) { capBlocked[why] = (capBlocked[why] ?: 0) + 1 }
        return why
    }

    /** Проигранная гонка (v63/v88): проигрыш по проекции на конец матча при PASSIVE_TICKS без удара по нам (v99: одна и та же
     *  для порога захвата и для стаи у свободного флага, см. USE_LOST_RACE_PACK_PARITY). */
    private fun lostRaceNow(): Boolean {
        if (!USE_LOST_RACE_CAPTURE) return false
        val ticksLeft = arenaInfo.ticksLimit - getTicks()
        val losingAtTheEnd = if (USE_LAST_CALL_PROJECTED) (ourScore - enemyScore) + (ourRate - enemyRate) * ticksLeft <= 0 else ourScore <= enemyScore
        val quiet = lastHurtTick == 0 || getTicks() - lastHurtTick >= FARMER_QUIET   // тишина (v65, см. FARMER_QUIET)
        // КЛАПАН ПО РАЗМЕНУ, А НЕ ПО ТИШИНЕ (v218, решение оператора). Здесь стояло `quietShort` — «сто тиков
        // ПОДРЯД без единого полученного удара». Против бота, чей пикет нас постоянно задевает, такой тишины не
        // наступает никогда, и послабленный пол PARITY_FLOOR_LOST не открывался ни разу: разбор двадцати матчей
        // v217 дал 1531 отказ по паритету в поражениях против 40 в победах, а в проигранных забегах 582, 1753 и
        // 2407 — при том, что в けろびー#12 (#20) за все 1900 тиков не разменяно НИ ОДНОГО хита с обеих сторон.
        // Признак заменён на СОБСТВЕННОЕ определение боя в этом файле — `netDamage` (см. STALL_DAMAGE): «за
        // STALL_TICKS любая сторона потеряла STALL_DAMAGE хитов». Нового числа не заводится, и оно вычисляется
        // из живых хитов обеих сторон, а не названо под текущего соперника. По замеру делит правильно: в #20
        // окно показало ledgerw=0/0/0 (0 < 300 — клапан открыт), в аннигиляции #1 потери шли ~3000 за окно
        // (много больше 300 — клапан закрыт, доктрина паритета цела).
        // ⚠️ Доктрина НЕ меняется: пол по-прежнему сравнивает нашу мощь С дебаффом флага против его без дебаффа,
        // меняется только признак «бой идёт». Меру мощи оператор трогать запретил — она остаётся зажатой в ноль
        // его лечением, и это открытый предмет
        // ...и признак сужен до НАШИХ потерь (v218, замер гейта). Первая редакция брала `netDamage` целиком —
        // «за окно потеряла ЛЮБАЯ сторона», — и уронила две строки лагеря: match31:camp отрыв 5189 -> 2185,
        // match34:camp уничтожение с t=951 на t=1212. Причина в асимметрии: пока мы безнаказанно бьём лагерь,
        // потери есть У НЕГО, признак говорит «бой идёт», и строгий пол возвращается там, где мы ВЫИГРЫВАЕМ
        // бой. Пол существует ради одного — не потерять НАШУ армию за флаги; значит и спрашивать надо про наши
        // потери. Окно и порог те же (LEDGER_WINDOW = STALL_TICKS, STALL_DAMAGE), новых чисел по-прежнему нет
        val quietShort = if (USE_LOST_RACE_BY_LEDGER) ourLostWindow < STALL_DAMAGE
            else lastHurtTick == 0 || getTicks() - lastHurtTick >= PASSIVE_TICKS
        return if (USE_LOST_RACE_PROJECTED) losingAtTheEnd && quietShort
            else stalemateNow && quiet && ourScore <= enemyScore && ourRate <= enemyRate
    }

    /** Флаги, на которые наши крипы уже шагают в ЭТОТ тик (см. planCapture): два захвата одним тиком — D5 армией и H4
     *  скаутом — каждый в отдельности проходил порог паритета, вместе дали 0.93 и разгром 12:0 (стенд m9 hunter, t=98). */
    private val plannedCaptures = HashSet<String>()
    private val rotatingIds = HashSet<String>()   // бойцы в ротации (см. ROTATE_OUT)
    private val rotateSince = HashMap<String, Int>()   // тик выхода в ротацию (замер длительности, см. USE_ROTATE_OVER_SLOT)
    private val NO_FLOW = IntArray(10000) { -1 }
    private val keeperIds = HashMap<String, String>()   // хранитель флага → id флага (см. KEEP_RANGE)
    private val enemyHitsHist = ArrayDeque<Int>()         // сумма хитов врага за STALL_TICKS тиков (чистый урон)
    private val marchHist = ArrayDeque<Int>()             // клетка центра вооружённой массы за MARCH_STALL_TICKS тиков
    private val armyDistHist = ArrayDeque<Int>()          // дистанция между центрами армий за CHASE_WINDOW тиков (см. третья сетка)
    private val ourHitsHist = ArrayDeque<Int>()           // и наша: бьют только нас — это бой, не простой
    private var preyNearTicks = 0                         // тиков подряд с пикетом (см. STALL_PICKET) в досягаемости
    private var stallUntil = 0
    private var stalledNow = false                        // бесплодная охота (см. STALL_TICKS) — снимает и запрет захвата в контакте
    private var stalemateNow = false                      // отставание с меньшим темпом дольше BEHIND_PATIENCE (см. PARITY_FLOOR_LOST)
    private var standoffTicks = 0                         // тиков подряд стоящей линии врага (см. PRESS_PATIENCE)
    private var pressing = false                          // прижим включён (см. USE_PRESS)
    private val meleeDistHist = ArrayDeque<Int>()         // дистанция их мили до наших вооружённых за окно терпения (см. PRESS_CLOSING)
    private val centreDistHist = ArrayDeque<Int>()        // дистанция между центрами вооружённых армий за то же окно (см. standingNow)
    private val approachHist = ArrayDeque<Int>()          // то же расстояние, но пишется и БЕЗ контакта (см. enemyApproaching)
    private val stalemateOurHist = ArrayDeque<Int>()      // сумма наших хитов за окно (см. stalemateNow)
    private val stalemateHisHist = ArrayDeque<Int>()      // и его — чтобы отличить пат от проигранного размена
    private val hisTouchHist = ArrayDeque<Int>()           // то же по ЕГО мили: цена флага A3 держится на обеих долях
    private var hisTouchShare = 1.0
    private val touchHist = ArrayDeque<Int>()              // доля наших мили, стоявших вплотную к врагу, по тикам контакта
    private var touchShare = 1.0                          // она же за окно; до заполнения окна — единица, чтобы вход в бой не менялся
    private var touchMin = 1.0                            // минимум за матч — прибор
    private var meleeBackTicks = 0                        // прибор: тиков, в которые мили ставился ПОЗАДИ строя (v195)
    private var leadTicks = 0                             // прибор: тиков, в которые ряд целился на клетку ближе (v196)
    private val rungCount = HashMap<String, Int>()        // перепись решений (v203): какая ветка ЦЕЛИ выбрана, сколько раз
    private val stepCount = HashMap<String, Int>()        // ...и какая ветка ШАГА
    private val passCount = HashMap<String, Int>()        // ...и какой проход раздачи командира сколько клеток назначил
    private var planGunsIn = 0; private var planGunsAll = 0        // прибор согласованности строя (v200)
    private var planMeleeHealed = 0; private var planMeleeAll = 0
    private var planHealBehind = 0; private var planHealAll = 0
    private var outOfFireTicks = 0                        // крипо-тиков, в которые мили уводился из его кольца
    private var stalemateTicks = 0                        // сколько тиков подряд бой не двигается ни в чью пользу
    private var stalemateGap = 0                          // тиков подряд без контакта (см. STALEMATE_GAP)
    private var patMax = 0                                // самый длинный пат за матч — прибор, чтобы правило не мерили вслепую
    private var stripTicks = 0                            // тиков, в которые залп сводился на ОДНОГО его лекаря
    /** Тик погони за целью прижима: дистанция от наших мили, клетка цели и клетка нашего ближайшего мили (см. PRESS_GIVEUP, v96). */
    private class ChaseSample(val d: Int, val eCell: Int, val meleeCell: Int)
    private val pressChase = HashMap<String, ArrayDeque<ChaseSample>>()  // погоня за целью прижима по тикам (см. PRESS_GIVEUP)
    private val ourCentreHist = ArrayDeque<Int>()        // клетка центра наших вооружённых за окно терпения (см. USE_STANDING_LINE_HOLDS)
    private var yieldingTick = -1                        // последний тик, когда наша линия отступала (лог v96)
    private val lastArmedRange = HashMap<String, Int>()   // враг → дистанция до ближайшего нашего боеспособного тик назад (см. threatOf)
    private val pressGiveUp = HashMap<String, Int>()      // цель прижима, от которой отказались, → тик, до которого
    private val SLOT_ORDER = intArrayOf(0, -1, 1, -2, 2, -3, 3, -4, 4)

    private fun planCapture(ctx: Ctx, step: Position?) {
        if (step == null) return
        ctx.flags.firstOrNull { !it.ours && it.pos.x == step.x && it.pos.y == step.y }?.let { plannedCaptures.add(it.id) }
    }

    /** Мощь сторон, если мы возьмём ещё этот флаг (и те, на которые уже шагаем в этот тик): наша — с их дебаффами;
     *  вражья — без них, если флаги были его. */
    private fun powerAfter(ctx: Ctx, f: FlagInfo): Pair<Double, Double> =
        powerAfterFor(ctx, if (USE_CAPTURE_MEASURES_CORE) ctx.army else ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }, ctx.combatEnemies, f)

    /** То же для заданной стороны и группы врага (v95: пул проверяет ядро без крипа с дебаффом его флага-цели). */
    private fun powerAfterFor(ctx: Ctx, side: List<Creep>, opp: List<Creep>, f: FlagInfo): Pair<Double, Double> {
        val taking = HashSet(plannedCaptures); taking.add(f.id)
        // и флаг-цель армии (v121): захват, который уже идёт, — часть состояния «после»
        if (USE_TAKING_INCLUDES_OBJECTIVE) objectiveFlagId?.let { id -> if (ctx.flags.any { it.id == id && !it.ours }) taking.add(id) }
        fun mods(mine: Boolean): HypoMods {
            fun k(type: String): Double {
                val now = ctx.flags.count { it.mine == mine && it.type == type }
                // его флаги В ПОЛЁТЕ (v128, USE_HIS_FLAGS_IN_FLIGHT): свободный флаг с его вооружённым вплотную — его в состоянии «после»,
                // и пол паритета видит симметричный размен, а не наш дебафф против его чистой армии (гастролёр берёт D5 на 39–41-м)
                fun inFlight(fl: FlagInfo) = USE_HIS_FLAGS_IN_FLIGHT && !fl.ours && !fl.theirs && fl.id !in taking && ctx.combatEnemies.any { e -> hasWeapon(e) && getRange(e, fl.pos) <= 1 }
                val after = ctx.flags.count { it.type == type && (if (mine) (it.ours || it.id in taking) else ((it.theirs && it.id !in taking) || inFlight(it))) }
                return stackMul(type, after) / stackMul(type, now).coerceAtLeast(0.01)
            }
            return HypoMods(ranged = k(EFF_RANGED_ATTACK_MODIFIER), melee = k(EFF_ATTACK_MODIFIER), heal = k(EFF_HEAL_MODIFIER), hits = 1.0 / k(EFF_DAMAGE_TAKEN_MODIFIER))
        }
        val ourMods = mods(true)
        val theirMods = mods(false)
        // для captureAllowed сторона — армия с вооружёнными и лечащими бегунами (v59): паритет захвата — страховка от
        // аннигиляции стороны, а отряженные в бегуны (см. USE_DETACH) живы и вооружены. Ядро без пяти отряжённых стояло в
        // паритете (2918 против 2954), захват был запрещён ВСЕМ, и четверо отряжённых 800 тиков стояли POISED в клетке от
        // свободных D5, A3, R3 и H4 — 3174:22931, двенадцатый проигрыш фермеру (матч 139); до отряда, при 1,41, захваты были
        // разрешены и скаутам
        return powerOf(side, opp, ourMods, theirMods) to powerOf(opp, side, theirMods, ourMods)
    }

    /** Цена флага в силе — доля нашей мощи, которая останется после захвата (1 — бесплатно): флаг лечения
     *  для армии почти без лекарей дёшев, флаг уязвимости стоит всем; дорогие берутся последними. */
    private fun captureCost(ctx: Ctx, f: FlagInfo): Double {
        if (f.ours || ctx.combatEnemies.isEmpty()) return 1.0
        // ОДИН СОСТАВ ПО ОБЕ СТОРОНЫ ДРОБИ (v216, см. USE_CAPTURE_COST_ONE_SIDE): знаменатель обязан считаться по
        // той же стороне, что и числитель в powerAfter, иначе отношение выходит больше единицы и обрезается в 1,0
        val side = if (USE_CAPTURE_COST_ONE_SIDE && !USE_CAPTURE_MEASURES_CORE)
            ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) } else ctx.army
        val now = ourPowerOf(side, ctx.combatEnemies)
        if (now <= 0.0) return 1.0
        return (powerAfter(ctx, f).first / now).coerceIn(0.0, 1.0)
    }

    // ==================== захватчики ====================

    /** Флаг, за которым стоит идти захватчику: не наш и без врага на клетке, или наш пустой (охрана клеткой). */
    private fun wantsRunner(f: FlagInfo): Boolean {
        val occ = f.occupant
        if (occ != null && !occ.my) return false
        return !f.ours || occ == null
    }

    private fun runRunners(ctx: Ctx) {
        val runners = ctx.runners
        idleRunnerIds.clear()
        if (runners.isEmpty()) { runnerFlag.clear(); return }
        runnerFlag.keys.retainAll { id -> runners.any { it.id == id } }
        val flagById = ctx.flags.associateBy { it.id }
        fun dbg(s: Creep, mode: String, f: FlagInfo?, step: Position? = null) {
            // ПРИБОР ЗАБЕГА (v216): все ветки поведения бегуна проходят ровно здесь, поэтому счёт стоит тут, а не
            // в каждой из них. Считается ВСЕГДА, независимо от DEBUG_LOG: прибор, который виден только в логе с
            // подробностями, нельзя сложить по серии
            val tag = mode.substringBefore(':')
            runnerMode[tag] = (runnerMode[tag] ?: 0) + 1
            runnerModeN++
            // ...и цена простоя В ОЧКАХ, а не в тиках: тик у флага, который нельзя взять, стоит его score.
            // Разбор v214 считал эту величину вручную («166 тиков x 3 очка ~ 500, матч проигран с разрывом 292»)
            if (tag == "POISED" && f != null) poisedCost += f.score
            if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
                println("  r${s.id} (${s.x},${s.y}) ${bodySummary(s)} hits=${s.hits} $mode flag=${f?.let { "(${it.pos.x},${it.pos.y})${typeChar(it.type)}${it.score}my=${it.mine}" } ?: "-"} fatigue=${s.fatigue} step=${step?.let { "(${it.x},${it.y})" } ?: "stay"}${if (TrafficManager.isStuck(s.id)) " STUCK" else ""}")
            }
        }
        // назначение — глобальное жадное паросочетание по ценности (лучшая пара «захватчик-флаг» первой),
        // НЕ зависящее от порядка обхода: обход в порядке текущих назначений менял очерёдность от тика к
        // тику, два скаута по очереди отбирали друг у друга центральный флаг и полторы тысячи тиков
        // шагали туда-обратно на одной клетке, ни разу не выйдя за неё (матч 1). Взявший флаг идёт за
        // следующим НЕ НАШИМ; сидеть на своём — когда чужих свободных на всех не хватает
        class Cand(val runner: Creep, val flag: FlagInfo, val value: Double)
        val cands = ArrayList<Cand>()
        // страховка CPU (v131): тик уже дороже CPU_GUARD_MS — бегуны оставляют прежние флаги, кандидаты не пересчитываются
        val cpuGuard = USE_CPU_GUARD && getTicks() > 1 && cpuMs() > CPU_GUARD_MS
        if (cpuGuard && DEBUG_LOG) println("cpu t=${getTicks()} guard: runners keep their flags (${(cpuMs() * 10).toInt() / 10.0}ms)")
        if (!cpuGuard) for (s in runners) {
            val currentId = runnerFlag[s.id]
            val armedRunner = hasWeapon(s)
            for (f in ctx.flags) {
                val occ = f.occupant
                // занято (чужим — ждём отряд; своим — тот и держит). Вооружённый бегун (отряд, см. USE_DETACH) идёт на флаг с
                // ОДИНОЧНЫМ врагом слабее себя — в матче 126 отряд стоял POISED в клетке от D5, пока на нём сидел его крип
                if (occ != null && occ.id != s.id) {
                    if (!armedRunner || occ.my) continue
                    val e = ctx.enemyCreeps.firstOrNull { it.x == f.pos.x && it.y == f.pos.y } ?: continue
                    if (ctx.enemyCreeps.any { it.id != e.id && getRange(it, f.pos) <= ENGAGE_RANGE }) continue
                    if (ourPowerOf(listOf(s), listOf(e)) <= enemyPowerOf(listOf(e), listOf(s))) continue
                }
                val flow = flowTo(ctx, f.pos)
                val ticks = pathTicks(s, flow, s.x * 100 + s.y)
                if (ticks >= Int.MAX_VALUE / 4) continue
                // стая у флага — охрана рядом И те, кто дойдёт до него раньше нас: скаут шёл к дальнему H4, пока
                // армия врага шла туда же, и вошёл в неё (матч 3, t=70–87); охраны в 11 клетках было мало.
                // Для вооружённого бегуна стая — только та, что сильнее его (v57)
                val pack = packAt(ctx, f.pos, flow, ticks)
                // тихий фермер бегуну не стая (v105, USE_FARMER_RUNNER_PACK_FREE); безоружному скауту — по-прежнему стая
                if (pack.isNotEmpty() && !(USE_FARMER_RUNNER_PACK_FREE && farmerQuietNow && armedRunner) &&
                    (!armedRunner || enemyPowerOf(pack, listOf(s)) >= ourPowerOf(listOf(s), pack))) continue
                // при охотнике (см. escapeFlows) флаг без выхода — карман: три безоружных крипа сидели на угловых флагах,
                // пока армия врага шла к ним, и были добиты по одному — последний на 545-м тике, аннигиляция при +5000
                // очков (матч 13)
                // СВОБОДНЫЙ ФЛАГ БЕГУНА (v130, USE_RUNNER_FREE_FLAG): вето запаса выхода не касается бегуна без оружия, если его ближайший
                // угрожающий крип дальше от флага, чем путь бегуна плюс порог его бегства (SCOUT_FLEE_TRIGGER): бегун дойдёт раньше,
                // чем угроза войдёт в его порог. Матч 407: армия 530 тиков в EVADE при его армии в 47 клетках, бегун scout_1 всё
                // время RESERVE — у каждого флага запас выхода отрицателен или неизвестен; бегун — M1 на 100 хитов, армию не тянет
                val hisNearestToFlag = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }.minOfOrNull { getRange(it, f.pos) } ?: Int.MAX_VALUE / 4
                val freeFlag = USE_RUNNER_FREE_FLAG && !armedRunner && hisNearestToFlag > ticks + SCOUT_FLEE_TRIGGER
                if (escapeFlows.isNotEmpty() && !freeFlag && exitMargin(ctx, f.pos, ticks) < 0) continue
                // свой пустой флаг стоит половину — но СИДЯЩИЙ на нём закрывает клетку от чужих бегунов (матч 2:
                // центральный D5 забрал вражеский M1, пока армия уходила за соседним флагом, и вернуть его было
                // некому); чужой — двойной размен; флаг, который порог силы сейчас не разрешает, — пятую часть
                // (ждать у него можно, но сидеть на своём полезнее); дорогой по силе — позже дешёвого (см.
                // captureCost); текущий — с премией
                val gain = (if (f.ours) 0.5 * f.score else f.swing) * captureCost(ctx, f)
                val horizon = if (USE_RUNNER_HORIZON && farmerQuietNow) maxOf(1, arenaInfo.ticksLimit - getTicks() - ticks).toDouble() else 1.0 / (ticks + 5)
                val value = gain * horizon *
                    (if (f.id == currentId) 1.25 else 1.0) * (if (!f.ours && !captureAllowed(ctx, f)) 0.2 else 1.0)
                cands.add(Cand(s, f, value))
            }
        }
cpuMark("r.cands")
        cands.sortByDescending { it.value }
        val assigned = HashSet<String>()
        val taken = HashSet<String>()
        if (cpuGuard) for (s in runners) runnerFlag[s.id]?.let { id -> if (flagById[id] != null) { assigned.add(s.id); taken.add(id) } }
        for (c in cands) {
            if (c.runner.id in assigned || c.flag.id in taken) continue
            assigned.add(c.runner.id)
            taken.add(c.flag.id)
            runnerFlag[c.runner.id] = c.flag.id
        }
        // пары (v94): флаг со стаей, с которой один не справится, — двум ближайшим свободным вооружённым, если справятся вдвоём
        if (USE_RUNNER_PAIRS && !cpuGuard) {
            for (f in ctx.flags) {
                if (f.ours || f.id in taken) continue
                if (f.occupant?.my == true) continue
                val free = runners.filter { it.id !in assigned && hasWeapon(it) }.sortedBy { getRange(it, f.pos) }.take(2)
                if (free.size < 2) continue
                val flow = flowTo(ctx, f.pos)
                val ticks = free.maxOf { pathTicks(it, flow, it.x * 100 + it.y) }
                if (ticks >= Int.MAX_VALUE / 4) continue
                val occ = ctx.enemyCreeps.filter { it.x == f.pos.x && it.y == f.pos.y }
                val pack = (packAt(ctx, f.pos, flow, ticks) + occ).distinctBy { it.id }
                if (pack.isEmpty()) continue
                if (ourPowerOf(free, pack) <= enemyPowerOf(pack, free)) continue
                if (escapeFlows.isNotEmpty() && exitMargin(ctx, f.pos, ticks) < 0) continue
                for (r in free) { assigned.add(r.id); runnerFlag[r.id] = f.id }
                taken.add(f.id)
            }
        }
        for (s in runners) if (s.id !in assigned) runnerFlag.remove(s.id)

        for (s in runners) {
            val f = runnerFlag[s.id]?.let { flagById[it] }
            val onIt = f != null && s.x == f.pos.x && s.y == f.pos.y
            val nearby = ctx.combatEnemies.filter { getRange(s, it) <= RANGED_RANGE + 2 }
            val underFire = InfluenceMap.damageAt(s.x, s.y, ctx.combatEnemies) > 0.0
            // мили-бегун (отряд) рубит вплотную (v57): healAndShoot за бегунов только стреляет, удар мили выдаёт цикл армии
            if (hasMelee(s)) ctx.enemyCreeps.filter { getRange(s, it) <= 1 }.minByOrNull { it.hits }?.let { s.attack(it) }
            // захватчик без замены: от врага «с боем» ближе SCOUT_FLEE_TRIGGER — прочь (пустой MOVE ходит клетку за тик и
            // по болоту, где стрелок вязнет), даже с флага: флаг останется нашим, пока враг сам на него не встанет
            val threats = ctx.combatEnemies.filter { getRange(s, it) <= SCOUT_FLEE_TRIGGER && threatening(it, ctx.enemyCreeps) }
            if (canMove(s) && (underFire || threats.isNotEmpty())) {
                // поиск пути бегства может не дать шага (скаут в матче 3 «бежал» на месте три тика и погиб) —
                // тогда жадно: соседняя клетка подальше от врагов и под меньшим огнём; в опасности шаг делается ВСЕГДА,
                // и на не лучшую клетку тоже: скаут у стены (4,40) «бежал» стоя тридцать тиков рядом с боем и погиб
                // (матч 12) — стоящего враг на равной скорости достаёт следующим тиком, идущего нет
                val foes = threats.ifEmpty { ctx.combatEnemies }
                val danger = underFire || nearby.isNotEmpty()
                val step = fleeStep(s, foes, ctx.dangerMatrix, SCOUT_FLEE_RANGE) ?: greedyFlee(ctx, s, foes, force = danger)
                if (step != null) TrafficManager.request(s, step, RUNNER_PRIORITY)
                dbg(s, "FLEE", f, step)
                continue
            }
            if (f == null) {
                // все флаги при деле: к армии, за её спиной
                val step = if (s.getRangeTo(ctx.ourCentroid) > POST_STANDOFF + 2) pathStep(s, ctx.ourCentroid, POST_STANDOFF + 2, crowdMatrixOf(ctx, -1)) else null
                if (step != null) TrafficManager.request(s, step, RUNNER_PRIORITY)
                idleRunnerIds.add(s.id)
                dbg(s, "RESERVE", null, step)
                continue
            }
            // выход закрывается (см. exitMargin): с флага — в лучшую точку выхода, пока устье открыто
            if (f != null && escapeFlows.isNotEmpty() && getRange(s, f.pos) <= 2 && exitMargin(ctx, f.pos, 0) < 0) {
                val to = runnerEscape(ctx, s)
                if (to != null) {
                    val step = pathStep(s, to, 1, ctx.dangerMatrix)
                    if (step != null) TrafficManager.request(s, step, RUNNER_PRIORITY)
                    dbg(s, "EXIT", f, step)
                    continue
                }
            }
            if (onIt) {
                dbg(s, if (f.ours) "HOLD" else "HOLD_WAIT", f)
                continue
            }
            // брать ли флаг сейчас (дебафф): нельзя — ждём рядом, шаг на клетку сделаем, когда станет можно
            val block = captureBlock(ctx, f)
            val allowed = block == null
            val range = if (allowed) 0 else 1
            // свой назначенный флаг открыт для шага, остальные не наши — стены (см. Ctx.flagCells)
            // при запрете захвата клетка флага — стена и для его же бегуна: путь к «зазору 1» шёл ЧЕРЕЗ флаг, и скаут брал R3
            // на 49-м при уклонении с 3-го (матч 56), как и в четырёх боях с けろびー до правила v34/v35
            // ПАРА ИДЁТ ВМЕСТЕ (v158): на флаг под стаей отправляются двое (см. USE_RUNNER_PAIRS), потому что один не
            // справится, — но шли они каждый своим путём и приходили порознь, то есть по одному против той же стаи.
            // Идущий впереди ждёт отставшего: тот же кулак, только на двоих
            val mate = if (!USE_PAIR_TOGETHER) null else runners.firstOrNull { o ->
                o.id != s.id && runnerFlag[o.id] == f.id && canMove(o) }
            val waitForMate = mate != null && getRange(s, mate) > PAIR_KEEP && s.getRangeTo(f.pos) <= mate.getRangeTo(f.pos)
            val step = if (!waitForMate && s.getRangeTo(f.pos) > range) pathStep(s, f.pos, range, crowdMatrixOf(ctx, if (allowed) f.pos.x * 100 + f.pos.y else -1)) else null
            if (step != null) { TrafficManager.request(s, step, RUNNER_PRIORITY); planCapture(ctx, step) }
            // прибор наблюдения 4: бегун дошёл до флага, и ему запрещено на него встать. Пара «стоя/всего с целью»
            poisedAll++
            if (!allowed && step == null) poisedTicks++
            dbg(s, if (allowed) "TO_FLAG" else "POISED:$block", f, step)
        }
    }

    // ==================== армия ====================

    /** Поле к цели; не наши флаги — стены (кроме самой цели: flowFieldTo всегда открывает целевую клетку). */
    private fun flowTo(ctx: Ctx, target: Position, avoid: Boolean = false, near: Boolean = false): IntArray {
        val key = target.x * 100 + target.y + (if (avoid) 10000 else 0) + (if (near) 20000 else 0)
        val now = getTicks()
        val hit = flowCache[key]
        val at = flowCacheTick[key]
        // долгий срок — только ПОЛНОМУ полю к флагу (v131b): поле, посчитанное сверх бюджета BFS, ограничено NEAR_FLOW клетками, и
        // в кэше на тридцать тиков оно тридцать тиков говорило бегунам и армии «пути нет» (blitz 4-4 → 2-6, входы 3 хуже / 0 лучше)
        val ttl = if (near) 1 else if (USE_FLAG_FLOW_TTL && !avoid && flowFull[key] == true && ctx.flags.any { it.pos.x == target.x && it.pos.y == target.y }) FLOW_TTL_FLAG else FLOW_TTL
        if (hit != null && at != null && now - at < ttl) return hit
        if (hit != null && bfsCost >= BFS_BUDGET) return hit   // сверх бюджета — устаревшее поле
        // ...и СВЕРХ ВРЕМЕНИ ТОЖЕ, а не только сверх счётчика BFS (v184). Счётчик считает поля, а не миллисекунды, и
        // на втором тике матча их ещё мало: первый тик тратит около 185 мс из тысячи (built 55, prefetch 28, plan 25),
        // сторож на втором честно срабатывает на 63 мс, а следом всё равно запускается ПОЛНОЕ поле — и тик уходит
        // целиком с `Script execution timed out` в bfs. В двенадцати тестовых играх это случилось в пяти, поровну в
        // победах и поражениях, то есть разгромов не объясняет, но тик пропадает даром
        val bounded = near || bfsCost >= BFS_BUDGET ||
            (USE_CPU_GUARD && USE_FLOW_CPU_GUARD && now > 1 && cpuMs() > CPU_GUARD_MS)
        bfsThisTick++
        bfsCost += if (bounded) 0.25 else 1.0
        val f = DistanceMap.flowFieldTo(target, ctx.flagBlocked + (if (avoid) ctx.blocked + avoidCells(ctx) else ctx.blocked),
            maxDist = if (bounded) NEAR_FLOW else Int.MAX_VALUE)
        flowCache[key] = f
        flowFull[key] = !bounded
        flowCacheTick[key] = if (bounded && !near) -1000 else now
        return f
    }

    /** Клетки в AVOID_RANGE от СТОЯЩИХ боевых врагов — поле «в обход» ведёт мимо лагеря, а не сквозь него.
     *  Идущий враг не обходится: обход идущего навстречу разводил строй с поста в стороны за тик до
     *  столкновения, и рывок врага, прежде отбитый к 212-му тику, стал разгромом (стенд rush). */
    private var avoidCellsCache: List<Position>? = null
    private fun avoidCells(ctx: Ctx): List<Position> = avoidCellsCache ?: run {
        val seen = HashSet<Int>()
        val out = ArrayList<Position>()
        for (e in ctx.combatEnemies) for (dx in -AVOID_RANGE..AVOID_RANGE) for (dy in -AVOID_RANGE..AVOID_RANGE) {
            if (!stationary(e)) continue
            val x = e.x + dx; val y = e.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            if (seen.add(x * 100 + y)) out.add(InfluenceMap.cell(x, y))
        }
        avoidCellsCache = out
        out
    }

    /** Поле к НЕ-вражеской цели (флаг, пост, сбор, отход): в обход врагов, если оттуда, где стоит крип, такой
     *  путь есть, иначе обычное (матч 2 на стенде: маршрут к дальнему флагу вёл через стоящий отряд врага). */
    private fun flowAvoiding(ctx: Ctx, target: Position, creep: Creep, near: Boolean = false): IntArray {
        if (!USE_AVOID) return flowTo(ctx, target, near = near)
        val f = flowTo(ctx, target, true, near)
        return if (f[creep.x * 100 + creep.y] >= 0) f else flowTo(ctx, target, near = near)
    }

    /** Стая у цели: боевые враги рядом с ней и те, кто дойдёт до неё (своим телом по полю) не позже нас —
     *  из ХОДЯЧИХ: стоящий на месте STILL_TICKS тиков в стаю по «успеет дойти» не зачисляется (матч 1:
     *  армия врага не сделала ни шага за 1570 тиков, а «успевала» к каждому флагу, и армия простояла на посту). */
    private fun packAt(ctx: Ctx, pos: Position, flow: IntArray, ourTravel: Int): List<Creep> {
        if (!USE_PACK_MEMO) return ctx.combatEnemies.filter { getRange(it, pos) <= FLAG_GUARD_RANGE || (!stationary(it) && pathTicks(it, flow, it.x * 100 + it.y) <= ourTravel) }
        // МЕМО СТАИ (v132): пути его крипов к клетке флага ходятся раз в тик на флаг и поле, а не на каждого бегуна: пять отцепленных
        // бегунов × семь флагов × одиннадцать его крипов давали ~150 000 шагов по полю за тик (фаза r.cands 52–73 мс из 80–99 мс боевого
        // тика, восемь таймаутов в матче с Coldkimchi 07.09). Результат тот же
        if (packTicksTick != getTicks()) { packTicksCache.clear(); packTicksTick = getTicks() }
        val key = pos.x * 100 + pos.y
        val cached = packTicksCache[key]?.takeIf { it.first === flow }
        val ticksOf = cached?.second ?: HashMap<String, Int>().also { m ->
            for (e in ctx.combatEnemies) if (!stationary(e)) m[e.id] = pathTicks(e, flow, e.x * 100 + e.y)
            packTicksCache[key] = flow to m
        }
        return ctx.combatEnemies.filter { getRange(it, pos) <= FLAG_GUARD_RANGE || (ticksOf[it.id]?.let { t -> t <= ourTravel } == true) }
    }
    private val packTicksCache = HashMap<Int, Pair<IntArray, Map<String, Int>>>()   // клетка флага → (поле, id врага → тики пути), см. packAt
    private var packTicksTick = -1

    /** Сколько тиков враг не двигался (новый враг считается идущим). */
    private fun stationaryFor(e: Creep): Int = getTicks() - (enemyLastMove[e.id] ?: getTicks())

    /** Враг не двигался последние STILL_TICKS тиков. */
    private fun stationary(e: Creep): Boolean = stationaryFor(e) >= STILL_TICKS

    private class Objective(val flag: FlagInfo, val pack: List<Creep>, val value: Double, val travel: Int)

    /**
     * Флаг-цель армии: не наш, разрешённый к захвату; со стаей — по перевесу Ланчестера (ratio) и цене боя в
     * запасе хода группы (или в контакте); без стаи — просто идём. Ценность — очки размена за тик пути.
     * Текущая цель держится, пока проходит по мягкому порогу (гистерезис).
     */
    /** Враг, с которым есть бой: с уроном, либо лекарь, у которого рядом (в дальности лечения плюс шаг) свой с оружием
     *  в теле, живым или мёртвым (см. armedEnemies). */
    /**
     * МЕСТНЫЙ ПЕРЕВЕС В МАСШТАБЕ УДАРА. Поля влияния уже меряют это сами и строятся раз в тик (см. buildFields):
     * `ourBurstAt(его клетка)` — наш урон в тик ПО НЕМУ (мили штампуется радиусом 2, стрелок 3), `dangerAt(его
     * клетка)` — его урон по нашему крипу, вставшему рядом. Отношение и есть операторское «трое наших против
     * одного его»: 3×240 против его 240 читается как 3,0. Это два обращения к массиву, а не новая сущность.
     * Существующие `localAllies`/`localEnemies` меряют радиусы 8 и 11 — то есть почти всю армию, и потому на
     * вопрос «сильнее ли мы ЗДЕСЬ» ответить не могут.
     */
    /**
     * СКАУТ ВРАГА (v214, наблюдение оператора: «мы игнорируем крипов, у которых есть только мув-части — они
     * спокойно гуляют возле нашей армии, мы их пропускаем и не нападаем»). У каждой стороны их по два:
     * тело `M1h=100`, одна часть MOVE, сто хитов. Замер по записям: ОБА его скаута доживают до конца матча с
     * полными ста хитами, ни разу не обстрелянные, — и это они берут ему флаги.
     * Различитель точен и уже есть: `potentialOf` считает части ТЕЛА без проверки хитов, поэтому у остова
     * потенциал есть, а у скаута нулевой. Значит распоряжение v178 («разоружённый — не цель») не ослабляется
     * ни на йоту: оно про того, у кого оружие БЫЛО, а у скаута его не было никогда.
     */
    private fun scoutFoe(e: Creep): Boolean =
        InfluenceMap.potentialOf(e).let { it.melee + it.ranged + it.heal <= 0.0 } && canMove(e)

    private fun spotEdgeAt(e: Creep): Double {
        val k = e.x * 100 + e.y
        val d = InfluenceMap.dangerAt(k)
        return if (d <= 0.0) Double.MAX_VALUE else InfluenceMap.ourBurstAt(k) / d
    }

    private fun threatening(e: Creep, enemyCreeps: List<Creep>): Boolean {
        val q = InfluenceMap.profileOf(e)
        return q.melee + q.ranged > 0.0 || enemyCreeps.any { w -> w.id != e.id && getRange(w, e) <= HEAL_RANGE + 1 && w.body.any { it.type == ATTACK || it.type == RANGED_ATTACK } }
    }

    private fun chooseFlagObjective(ctx: Ctx, group: List<Creep>, pushRatio: Double, escapeNeeded: Boolean = false, onlyFlagId: String? = null): Objective? {
        if (group.isEmpty()) return null
        var best: Objective? = null
        for (f in ctx.flags) {
            objDropN++
            if (f.ours) { objDrop["ours"] = (objDrop["ours"] ?: 0) + 1; continue }
            if (onlyFlagId != null && f.id != onlyFlagId) { objDrop["cpu"] = (objDrop["cpu"] ?: 0) + 1; continue }   // страховка CPU (v131c)
            if (!captureAllowed(ctx, f)) { objDrop["gate"] = (objDrop["gate"] ?: 0) + 1; continue }
            // ЦЕЛЬ АРМИИ НЕ ДУБЛИРУЕТ ФЛАГ БЕГУНА (v216). Обе соседние раздачи это уже проверяют — `commandRace`
            // («флаг, взятый бегуном, не дублируем») и `grabberOf` (исключает флаг-цель), — а самая дорогая, цель
            // ВСЕЙ армии, не проверяла. При потолке в один-два работающих крипа на семи флагах дубль означает, что
            // работающий флаг остаётся ОДИН. Флаг, который бегуну брать запрещено, сюда всё равно не дойдёт: гейт
            // `captureAllowed` у них общий и стоит строкой выше
            // ...и только если бегун ДОЙДЁТ РАНЬШЕ. Первая редакция снимала флаг с любого назначения, и это
            // уронило гейт: строка match33:scatter перестала проходить, отрыв −33 691, три строки из 135 остались
            // без изменений. Причина: назначение `runnerFlag` держится и за убегающим, и за тем, кто стоит у флага
            // без права встать, — армия теряла цель, до которой бегун не дойдёт никогда
            if (USE_OBJECTIVE_NOT_RUNNERS && ctx.runners.any { r ->
                    runnerFlag[r.id] == f.id && getRange(r, f.pos) < group.minOf { getRange(it, f.pos) } }) {
                objDrop["dup"] = (objDrop["dup"] ?: 0) + 1; continue
            }
            val flow = flowTo(ctx, f.pos)
            val travel = group.maxOf { pathTicks(it, flow, it.x * 100 + it.y) }
            if (travel >= Int.MAX_VALUE / 4) { objDrop["nopath"] = (objDrop["nopath"] ?: 0) + 1; continue }
            if (escapeNeeded) {
                // покинутую точку уклонения армия не идёт «захватывать»: у R3 (13,49) счёт места упал, точка покинута — и
                // тут же выбрана целью в шести тиках, навстречу врагу (матч 12, t=188)
                val left = evadeLeft
                if (left != null && left.x == f.pos.x && left.y == f.pos.y) { objDrop["evadeLeft"] = (objDrop["evadeLeft"] ?: 0) + 1; continue }
                // только флаг с выходом (см. ESCAPE_MARGIN, REACTION_LAG): за H4 в угол (8,90) армия шла 52 тика, пока
                // враг шёл на неё с 80 клеток (матч 11); за R3 (13,49) — 41 тик вдоль западного края при спящем враге,
                // и тот пошёл на полпути (матч 12)
                if (exitMargin(ctx, f.pos, travel) < ESCAPE_MARGIN) { objDrop["exit"] = (objDrop["exit"] ?: 0) + 1; continue }
            }
            // ⚠️ ПРОБОВАНО И ОТВЕРГНУТО (матч 23): запрет марша длиннее, чем врагу дойти до нашей армии, когда мы впереди
            // с растущим отрывом. Ни одного проигрыша стенда он не предотвращает, а бот становится пассивен всякий раз,
            // когда ведёт: m23 rush 23279→21496, m22 wing 23180→21362, m17 wing 23638→21510, m7 sleeper 22462→20033.
            // Растянутую колонну чинит масса (см. MASS_RANGE), а не отказ от цели
            // стая без урона ничего не охраняет: три лекаря врага, лечащие друг друга, делали цену боя бесконечной для
            // ослабленной армии, и она 1500 тиков держала пост при шести свободных флагах (стенд m2 rush)
            val pack = packAt(ctx, f.pos, flow, travel).filter { threatening(it, ctx.enemyCreeps) }
            val current = f.id == objectiveFlagId
            val ratio = if (current) LOCAL_ENTER_RATIO else pushRatio
            // цена боя — гейт на ВХОД к охраняемому флагу (лазейка «уже в контакте» отправила армию к дальнему
            // флагу с девятью охранниками сквозь наступающую армию — стенд rush, t=61)
            // проигранная гонка (v99, USE_LOST_RACE_PACK_PARITY): стая у флага, у которого его вооружённых сейчас нет, — по паритету
            val lostRacePack = USE_LOST_RACE_PACK_PARITY && lostRaceNow() && pack.none { getRange(it, f.pos) <= ENGAGE_RANGE }
            val ok = pack.isEmpty() || (USE_FARMER_PACK_FREE && farmerQuietNow) ||
                (lostRacePack && ourPowerOf(group, pack) >= enemyPowerOf(pack, group) * PARITY_FLOOR) ||
                (ourPowerOf(group, pack) >= enemyPowerOf(pack, group) * ratio && fightCost(pack, group) <= group.maxOf { speedSlack(it) })
            if (!ok) { objDrop["pack"] = (objDrop["pack"] ?: 0) + 1; continue }
            objDrop["taken"] = (objDrop["taken"] ?: 0) + 1
            // гистерезис: текущая цель ценнее на четверть, чтобы не прыгать между равными; дорогой по силе — позже
            val value = f.swing * captureCost(ctx, f) / (travel + 10) * (if (current) 1.25 else 1.0)
            if (best == null || value > best.value) best = Objective(f, pack, value, travel)
        }
        return best
    }

    /** Точка отхода: дом и углы НАШЕЙ половины — достижимая и самая дальняя от центра армии врага (отход в
     *  дальний угол через всю карту вёл сквозь врага, и армию добивали по одному — стенд rush). */
    /** Враг уходит: за CHASE_WINDOW тиков отдалился от ТОГДАШНЕГО центра нашей армии больше чем на клетку. Кайтер
     *  держит дистанцию, и «дистанция до нас не растёт» его не выдаёт — выдаёт движение прочь от места, где мы были.
     *  Порог делает уходящим и блоб, шагнувший назад на две клетки: все двенадцать «неловимы» восемь тиков, huntable 0/12,
     *  наступление снято, армия к посту (матч 70, t=196–207, 223, 234, 554). ОТВЕРГНУТО стендом: порог «больше половины окна»
     *  (уходил дольше, чем стоял) — 66 строк хуже / 44 лучше: кайтеры добиваются медленнее на десятке карт (за ними гонятся
     *  дольше), россыпи m12/m19/m24/m29/m30 spread и m29/m30 farm из победы в проигрыш; гистерезис в самом наступлении —
     *  тоже (см. pushing). Открытая находка. */
    /** Страж своего флага (v222, см. USE_GUARD_IS_CATCHABLE): в дальности стражи его флага и за CHASE_WINDOW не отошёл от
     *  него больше чем на клетку. Считает пару прибора: из «уходящих» — стражи. */
    private fun guardsHisFlag(e: Creep): Boolean {
        val h = enemyCellHist[e.id] ?: return false
        if (h.size < CHASE_WINDOW) return false
        val old = h.first()
        val oldPos = InfluenceMap.cell(old / 100, old % 100)
        anchorEvasive++
        val held = flagsNow.any { f -> f.theirs && getRange(e, f.pos) <= FLAG_GUARD_RANGE && getRange(e, f.pos) <= getRange(oldPos, f.pos) + 1 }
        if (held) anchorHeld++
        return held
    }

    private fun evasive(e: Creep): Boolean {
        val h = enemyCellHist[e.id] ?: return false
        if (h.size < CHASE_WINDOW || ourCentroidHist.size < CHASE_WINDOW) return false
        val c0 = ourCentroidHist.first()
        val old = h.first()
        val cPos = InfluenceMap.cell(c0 / 100, c0 % 100)
        val oldPos = InfluenceMap.cell(old / 100, old % 100)
        return getRange(e, cPos) > getRange(oldPos, cPos) + 1
    }

    /** Ловим ли враг: вплотную к нашему вооружённому (MELEE_KEEP_RANGE), медленнее нашего самого быстрого или не
     *  уходит (см. evasive). Только за ловимым идут стая, охота, добивание и местный бросок (см. CHASE_WINDOW). */
    private fun catchable(e: Creep, armed: List<Creep>): Boolean {
        if (armed.any { getRange(e, it) <= MELEE_KEEP_RANGE }) return true
        // медленнее нас ТАМ, ГДЕ СТОИТ (v48): период на его клетке — в болоте тело с половиной MOVE ходит клетку в пять
        // тиков, и застрявший в болоте ловим, хотя на равнине он равен нам (матч 90, см. InfluenceMap.enemyOrigins)
        if (periodAt(e, e.x, e.y) > (armed.minOfOrNull { plainPeriod(it) } ?: 1)) return true
        if (!evasive(e)) return true
        // ...и страж своего флага (v222, см. USE_GUARD_IS_CATCHABLE) — стоит, а не уходит. Прибор считает в обеих сборках
        return guardsHisFlag(e) && USE_GUARD_IS_CATCHABLE
    }

    private fun retreatPoint(ctx: Ctx): Position {
        val enemy = ctx.enemyCentroid ?: return ctx.home
        // точка одна на весь отход, пока враг не ближе к ней, чем мы: смена точки на ходу ((3,96), потом (96,96))
        // развела армию по трём углам карты, и погоня добила всех поодиночке (матч 4)
        retreatTarget?.let { t -> if (getRange(t, enemy) > getRange(t, ctx.ourCentroid)) return t }
        val corners = listOf(InfluenceMap.cell(3, 3), InfluenceMap.cell(3, 96), InfluenceMap.cell(96, 3), InfluenceMap.cell(96, 96))
        // дом, пока враг не ближе к нему, чем мы; угол — только тогда: «выигрышный по дистанции» угол (3,96) в
        // матче 5 был ловушкой — армия отошла в него от кайтеров и была расстреляна, не имея куда шагнуть
        val enemyBetween = getRange(enemy, ctx.home) < getRange(ctx.ourCentroid, ctx.home)
        val candidates = if (enemyBetween) listOf(ctx.home) + corners.filter { DistanceMap.inOurHalf(it.x, it.y) } else listOf(ctx.home)
        var best = ctx.home
        var bestScore = Int.MIN_VALUE
        for (c in candidates) {
            val flow = flowTo(ctx, c)
            val reach = ctx.army.count { flow[it.x * 100 + it.y] >= 0 }
            if (reach == 0) continue
            // выигрыш дистанции от врага НА КЛЕТКУ ПУТИ: «самая дальняя от врага» точка (3,96) лежала за его
            // флангом — 66 клеток пути ради 62 дистанции, мимо его строя; дом в 17 клетках даёт 22
            val score = getRange(c, enemy) - getRange(c, ctx.ourCentroid)
            if (score > bestScore) { bestScore = score; best = c }
        }
        retreatTarget = best
        return best
    }

    /** Точки выхода: семь флагов и оба дома (углы — карманы, их нет; см. EVADE_SAFE). */
    /** Точки выхода: флаги, оба дома и ЧЕТЫРЕ угла карты. Флаги стоят между домами — на оси подхода врага, и с одними
     *  флагами «прочь» не существовало: уклонение от броска шло к R3 навстречу врагу 30 клеток и было поймано у флага
     *  (матч 34, t=3–57). Углы — то, что всегда лежит в стороне от оси. */
    private fun escapeCandidates(ctx: Ctx): List<Position> =
        ctx.flags.map { it.pos } + listOf(ctx.home, ctx.enemyHome) +
            // углы — только при броске: как постоянные кандидаты они меняли всякое уклонение (102 сценария в одну сторону,
            // 105 в другую, потеря армии m9 sleeper), а нужны они там, где флаги лежат на оси подхода
            (if (unflaggedRushNow) listOf(InfluenceMap.cell(3, 3), InfluenceMap.cell(3, 96), InfluenceMap.cell(96, 3), InfluenceMap.cell(96, 96)).map { passableNear(it) } else emptyList())

    /** Поля потока к точкам выхода и ход врага до каждой — раз в EVADE_EVAL_EVERY тиков (девять полей). */
    private fun refreshEscape(ctx: Ctx, armed: List<Creep>) {
        val now = getTicks()
        if (now - escapeAt < EVADE_EVAL_EVERY && escapeFlows.isNotEmpty()) return
        escapeAt = now
        escapeFlows.clear(); escapeTheirs.clear(); escapeNearest.clear()
        for (c in escapeCandidates(ctx)) {
            val key = c.x * 100 + c.y
            val flow = flowTo(ctx, c)
            escapeFlows[key] = flow
            var bestTicks = Int.MAX_VALUE / 4
            var bestCell = -1
            for (e in armed) {
                val t = pathTicks(e, flow, e.x * 100 + e.y)
                if (t < bestTicks) { bestTicks = t; bestCell = e.x * 100 + e.y }
            }
            escapeTheirs[key] = bestTicks
            escapeNearest[key] = bestCell
        }
    }

    /** Клетка после ticks шагов спуска по полю от start (враг идёт за нами к цели поля). */
    private fun projectAlong(flow: IntArray, start: Int, ticks: Int): Int {
        var cell = start
        var left = ticks
        while (left > 0 && flow[cell] > 0) {
            val cx = cell / 100; val cy = cell % 100
            var next = -1; var nv = flow[cell]
            for ((dx, dy) in DIRECTIONS) {
                val x = cx + dx; val y = cy + dy
                if (x < 0 || y < 0 || x > 99 || y > 99) continue
                val v = flow[x * 100 + y]
                if (v in 0 until nv) { nv = v; next = x * 100 + y }
            }
            if (next < 0) break
            cell = next; left--
        }
        return cell
    }

    /** Запас выхода из точки c при нашем прибытии туда через arrive тиков. Преследователь идёт ЗА НАМИ, к c, а не к
     *  выходам: ближайший к c враг проецируется по полю к c на approachRate × arrive шагов, и от этой клетки считается
     *  его путь к каждому другому выходу минус наш путь от c туда; лучший из них — запас. Фора «идёт к выходу
     *  мгновенно» браковала всякую цель при идущем на нас враге, и армия сидела дома до боя в кармане (стенд m10
     *  hunter, m8 army); без выхода точка — карман (матч 11). */
    private fun exitMargin(ctx: Ctx, c: Position, arrive: Int): Int {
        val ckey = c.x * 100 + c.y
        val flowC = escapeFlows[ckey] ?: return Int.MIN_VALUE / 2
        val start = escapeNearest[ckey] ?: return Int.MIN_VALUE / 2
        val theirsC = escapeTheirs[ckey] ?: return Int.MIN_VALUE / 2
        if (theirsC >= Int.MAX_VALUE / 4) return Int.MIN_VALUE / 2   // его путь неизвестен — выход не подтверждён (v54)
        // при броске (см. EVADE_EQUAL_RATIO) преследователь идёт за нами на ПОЛНОЙ скорости: проекция по замеренному
        // темпу (0.42 в паузе колонны) считала дом безопасным выходом, и армия ушла в свой угол под удар (матч 32)
        val rate = if (unflaggedRushNow) 1.0 else approachRate
        val pursuer = if (start < 0) -1 else projectAlong(flowC, start, minOf(theirsC, (rate * arrive).toInt() + REACTION_LAG))
        var best = Int.MIN_VALUE / 2
        for (d in escapeCandidates(ctx)) {
            if (d.x == c.x && d.y == c.y) continue
            val flow = escapeFlows[d.x * 100 + d.y] ?: continue
            val step = flowNear(flow, c)
            if (step < 0) continue
            val theirs = if (pursuer < 0) Int.MAX_VALUE / 4 else flowNear(flow, InfluenceMap.cell(pursuer / 100, pursuer % 100)).let { if (it < 0) Int.MAX_VALUE / 4 else it }
            best = maxOf(best, theirs - step)
        }
        return best
    }

    /** Значение поля в клетке или, если она закрыта (чужой флаг — препятствие в полях потока), в лучшей соседней плюс
     *  шаг: запас выхода читался в клетке чужого флага и был «нет пути» для всякого флага-цели (стенд m1 scouts). */
    private fun flowNear(flow: IntArray, p: Position): Int {
        val here = flow[p.x * 100 + p.y]
        if (here >= 0) return here
        var best = -1
        for ((dx, dy) in DIRECTIONS) {
            if (dx == 0 && dy == 0) continue
            val x = p.x + dx; val y = p.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            val v = flow[x * 100 + y]
            if (v >= 0 && (best < 0 || v + 1 < best)) best = v + 1
        }
        return best
    }

    /** Точка уклонения (см. EVADE_SAFE): из точек выхода — с наибольшим счётом (меньший из запасов прибытия и выхода);
     *  где стоим — только пока счёт не меньше EVADE_SAFE; прежняя держится, пока не хуже лучшей на EVADE_HYSTERESIS;
     *  null — карман, уходить некуда. */
    /** Точка выхода для одиночного бегуна: лучшая по меньшему из запасов прибытия и выхода на ЕГО пути, не та, где он
     *  стоит (см. evadePoint для армии). */
    private fun runnerEscape(ctx: Ctx, s: Creep): Position? {
        var best: Position? = null
        var bestScore = Int.MIN_VALUE
        for (c in escapeCandidates(ctx)) {
            if (getRange(c, s) <= 2) continue
            val key = c.x * 100 + c.y
            val flow = escapeFlows[key] ?: continue
            val theirs = escapeTheirs[key] ?: continue
            val ticks = pathTicks(s, flow, s.x * 100 + s.y)
            if (ticks >= Int.MAX_VALUE / 4) continue
            val score = minOf(theirs - ticks, exitMargin(ctx, c, ticks))
            if (best == null || score > bestScore) { bestScore = score; best = c }
        }
        return best
    }

    private fun evadePoint(ctx: Ctx, armed: List<Creep>, strikers: List<Creep>): Position? {
        val now = getTicks()
        val cur = evadeTarget
        val arrived = cur != null && getRange(ctx.ourCentroid, cur) <= EVADE_ARRIVED
        if (cur != null && !arrived && now - evadeEvaluatedAt < EVADE_EVAL_EVERY) return cur
        evadeEvaluatedAt = now
        // прибыли в другую точку — покинутая снова допустима (см. evadeLeft)
        evadeLeft?.let { l -> if (arrived && cur != null && (cur.x != l.x || cur.y != l.y)) evadeLeft = null }
        val left = evadeLeft
        var best: Position? = null
        var bestScore = Int.MIN_VALUE
        var bestArrive = 0
        var bestExit = 0
        var curScore = Int.MIN_VALUE
        // при броске (см. EVADE_EQUAL_RATIO) выход обязан быть ПРОЧЬ: не ближе к центру вражеской армии, чем мы сейчас.
        // Запас «мы придём первыми» считал R3 на оси подхода безопасным, и армия шла врагу навстречу (матч 34)
        val enemyCentre = if (unflaggedRushNow) centroidOf(armed) else null
        for (c in escapeCandidates(ctx)) {
            if (left != null && c.x == left.x && c.y == left.y) continue
            if (enemyCentre != null && getRange(c, enemyCentre) <= getRange(ctx.ourCentroid, enemyCentre)) continue
            val key = c.x * 100 + c.y
            val flow = escapeFlows[key] ?: continue
            val theirs = escapeTheirs[key] ?: continue
            // «ему не дойти» — это НЕИЗВЕСТНОСТЬ, не безопасность (v54): поле за бюджетом BFS даёт Int.MAX_VALUE / 4, и точка
            // получала запас 536870903 — армия ушла в угол (96,3) при его армии в 75 клетках к югу и была там стёрта (матч 114,
            // Coldkimchi, t=333); бегство вбок (v53) не включилось, потому что «лучшая точка» была положительной
            if (theirs >= Int.MAX_VALUE / 4) continue
            val ourTicks = strikers.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: continue
            if (ourTicks >= Int.MAX_VALUE / 4) continue
            val exit = exitMargin(ctx, c, ourTicks)
            // он там раньше нас — это марш в него (v79); выход нулевой — это карман (v87)
            if (USE_EVADE_NO_LOSING_RACE && (theirs - ourTicks < 0 || exit <= 0)) continue
            val score = minOf(theirs - ourTicks, exit)
            if (getRange(c, ctx.ourCentroid) <= EVADE_ARRIVED && score < EVADE_SAFE) { evadeLeft = c; continue }
            if (cur != null && c.x == cur.x && c.y == cur.y) curScore = score
            if (best == null || score > bestScore) { bestScore = score; best = c; bestArrive = theirs - ourTicks; bestExit = exit }
        }
        if (cur != null && !arrived && curScore >= bestScore - EVADE_HYSTERESIS && curScore > 0) return cur
        // ни одной точки с запасом — бегство направлением (см. fleePoint); точка с нулевым или отрицательным запасом — это шаг
        // сквозь преследователя или в угол (матч 80: (3,3) −40, дом 0, (96,96) 0)
        if (USE_FLEE_DIRECTION && (best == null || bestScore <= 0)) {
            val flee = fleePoint(ctx, armed)
            val edge = flee?.let { minOf(it.x, it.y, 99 - it.x, 99 - it.y) } ?: 99
            if (USE_NO_FLEE_TO_EDGE && flee != null && edge <= FLEE_EDGE_MIN) {
                if (DEBUG_LOG && (cur != null || getTicks() % (LOG_EVERY * 5) == 0)) println("evade: t=$now flee=(${flee.x},${flee.y}) refused — ${edge} from the edge, the army stands at the post (see USE_NO_FLEE_TO_EDGE)")
                evadeTarget = null
                return null
            }
            if (flee != null) {
                if (cur == null || cur.x != flee.x || cur.y != flee.y)
                    println("evade: t=$now flee=(${flee.x},${flee.y}) best=${best?.let { "(${it.x},${it.y})" } ?: "-"} score=$bestScore from=(${ctx.ourCentroid.x},${ctx.ourCentroid.y}) approach=${(approachRate * 100).toInt()}")
                evadeTarget = flee
                return flee
            }
        }
        if (best == null) { evadeTarget = null; return null }
        if (cur == null || cur.x != best.x || cur.y != best.y)
            println("evade: t=$now to=(${best.x},${best.y}) score=$bestScore arrive=$bestArrive exit=$bestExit from=(${ctx.ourCentroid.x},${ctx.ourCentroid.y}) approach=${(approachRate * 100).toInt()}")
        evadeTarget = best
        return best
    }

    /** Пост: центр наших флагов (их и держим), без флагов — дом; и НЕ БЛИЖЕ EVADE_RANGE к краю карты (v46). Матчи 78 и 80
     *  (Coldkimchi, стоячая линия при паритете, из контакта отхода нет): единственный наш флаг — угловой H4 (90,8), пост на
     *  нём, армия стояла в углу; когда он пошёл на нас, ни одна точка уклонения не имела запаса (лог evade: (96,3) 13, дальше
     *  (3,3) −40 сквозь него, дом с выходом 0, угол (96,96) с выходом 0) — контакт на 319-м и 510-м, армия стёрта при его
     *  16000/16000. Флаг остаётся нашим, пока на него не встанет чужой (хранитель встаёт, когда враг подходит, см. KEEP_RANGE);
     *  стоять на нём армии незачем, а угол — ловушка для равного по скорости. */
    private fun postPoint(ctx: Ctx): Position {
        // пост под безфлаговым броском — флаг нашей половины, ближний к ЦЕНТРУ (v129, USE_POST_TOWARD_CENTRE): армия ждёт конца
        // удержания в 25 от D5 у A3, а не в углу у R3; первый флаг по времени тот же, второй на тридцать тиков раньше (матчи 5, 8,
        // 19 серий 367–406: его шесть флагов к 80–91-му, наш второй на 83–140-м)
        val centreCell = InfluenceMap.cell(49, 49)
        val ourHalfFlag = if (USE_POST_OUR_FLAG) ctx.flags.filter { DistanceMap.inOurHalf(it.pos.x, it.pos.y) }
            .minByOrNull { if (USE_POST_TOWARD_CENTRE && unflaggedRushNow) getRange(it.pos, centreCell) else getRange(it.pos, ctx.ourCentroid) }?.pos else null
        // центральный флаг наш — пост на нём (v102, USE_POST_ON_CENTRE)
        val centre = if (USE_POST_ON_CENTRE) ctx.flags.firstOrNull { it.ours && it.type == EFF_DAMAGE_TAKEN_MODIFIER }?.pos else null
        val c = centre ?: centroidOf(ctx.flags.filter { it.ours }.map { it.pos }) ?: ourHalfFlag ?: ctx.home
        return if (!USE_POST_INSIDE) passableNear(c) else passableNear(InfluenceMap.cell(c.x.coerceIn(EVADE_RANGE, 99 - EVADE_RANGE), c.y.coerceIn(EVADE_RANGE, 99 - EVADE_RANGE)))
    }

    /** Бегство направлением (v46): когда ни одна точка выхода не даёт запаса (см. evadePoint), цель — клетка в EVADE_RANGE от
     *  нашего центра в том из восьми направлений, где после шага центр вооружённого врага дальше всего, среди направлений,
     *  чья клетка не ближе EVADE_RANGE к краю (у края направлений вдвое меньше, в углу — вчетверо: матчи 78, 80). Точки
     *  выхода (флаги, дом, углы) при равной скорости преследователя все «за ним» или без выхода, и армия шла в наименее
     *  плохую — в угол. */
    private fun fleePoint(ctx: Ctx, armed: List<Creep>): Position? {
        val ec = centroidOf(armed) ?: return null
        val oc = ctx.ourCentroid
        // отступ от края — не больше нынешнего: у края все направления вдоль края запрещались, оставались только внутрь, и
        // армия с (29,6) пошла на (52,32) наискосок МИМО его центра (30,30) — перехвачена на 69-м, стёрта к 120-му (матч 83,
        // けろびー боевой, которого v45 била). Направление обязано уводить: скалярное произведение с вектором «от него к нам»
        // положительно; из допустимых — то, где его центр после шага дальше всего
        val margin = minOf(EVADE_RANGE, oc.x, oc.y, 99 - oc.x, 99 - oc.y).coerceAtLeast(0)
        val ax = oc.x - ec.x; val ay = oc.y - ec.y
        // ВБОК, когда «прочь» некуда (v53): из домашнего угла каждое направление прочь от его центра уводит за карту — матч 110,
        // бросок боевого けろびー с 3-го тика, уклонение из угла в угол, контакт у (79,81)–(93,93), армия стёрта к 150-му; тот же
        // бой в открытом поле выигран пять раз. Направление допустимо, если конец шага не ближе EVADE_RANGE к его центру:
        // сначала уводящие (скалярное произведение > 0), затем боковые; бой, если придёт, придёт в поле.
        // НАХОДКА (матч 115, не исправлено): у верхнего края при враге точно к югу «прочь» — за картой, и знак крошечного
        // бокового смещения его центра решал запад/восток: (5,3) на 56-м, (3,3) на 61-м, (50,6) на 71-м, (57,6) на 76-м —
        // центр армии за 20 тиков (30,3)→(28,3)→(25,3)→(27,3)→(30,3), контакт на 77-м. Ранжирование по расстоянию с
        // гистерезисом (v55-опыт) гейт прошло, но 25 строк хуже / 29 лучше — то же дрожание было во всех девятнадцати
        // победах над тем же соперником, решил не отход, а бой (см. covered)
        fun pick(away: Boolean): Position? {
            var best: Position? = null
            var bestD = -1
            for ((dx, dy) in DIRECTIONS) {
                if (dx == 0 && dy == 0) continue
                val dot = dx * ax + dy * ay
                if (if (away) dot <= 0 else dot < 0) continue
                val x = oc.x + dx * EVADE_RANGE; val y = oc.y + dy * EVADE_RANGE
                if (x < margin || y < margin || x > 99 - margin || y > 99 - margin) continue
                val c = passableNear(InfluenceMap.cell(x, y))
                val d = getRange(c, ec)
                if (d > bestD) { bestD = d; best = c }
            }
            return best?.takeIf { getRange(it, ec) >= (if (away) getRange(oc, ec) + 1 else EVADE_RANGE) }
        }
        return pick(true) ?: pick(false)
    }

    /** Ближайшая проходимая клетка: центр наших флагов попал в стенной блок, поле к нему было пустым (flow=-1), и
     *  армия стояла на месте, пока враг подходил (матч 11, t=90–103). */
    private fun passableNear(p: Position): Position {
        if (!DistanceMap.isTerrainWall(p.x, p.y)) return p
        for (r in 1..30) for (dx in -r..r) for (dy in -r..r) {
            if (maxOf(abs(dx), abs(dy)) != r) continue
            val x = p.x + dx; val y = p.y + dy
            if (x in 0..99 && y in 0..99 && !DistanceMap.isTerrainWall(x, y)) return InfluenceMap.cell(x, y)
        }
        return p
    }

    private fun runArmy(ctx: Ctx) {
        val army = ctx.army
        if (army.isEmpty()) return
        val allies = ctx.myCreeps
        val enemyCreeps = ctx.enemyCreeps
        val combatEnemies = ctx.combatEnemies
        updateKeepers(ctx, army)

        val strikers = army.filter { fullSpeed(it) && hasWeapon(it) && it.id !in keeperIds }
        // враги, с которыми есть бой: с уроном — и лекари, у которых рядом (в дальности лечения плюс шаг) есть свой с
        // оружием в теле, живым или мёртвым: такого лекарь вернёт в строй за шесть тиков (стенд m2 rush: армия ушла за
        // флагами от лекарей с обломками, и через сто тиков те вернулись в полном теле). Стая из одних лекарей при
        // скаутах (сила 0) не повод для боя: два уцелевших лекаря врага кайтили в четырёх клетках 1700 тиков, армия
        // в ДОБИТЬ то гналась, то сбивалась в кучу и не шла за флагами, пока скауты врага брали пять (m7 rush)
        val armedEnemies = combatEnemies.filter { threatening(it, enemyCreeps) }
        // сомкнутая масса врага — та же мера, что в postureOf (см. enemyMassed): шесть и больше вооружённых, две трети
        // которых в MASS_RANGE от их центроида. Считается раз на тик, а не на крипа (v135)
        val enemyMassedNow = armedEnemies.size >= 6 && centroidOf(armedEnemies)?.let { c ->
            armedEnemies.count { getRange(it, c) <= MASS_RANGE } * 3 >= armedEnemies.size * 2 } == true
        kiteNow = 0
        kiteMassed = enemyMassedNow
        planStrict = 0; planLoose = 0
        // чистый урон врагу за окно: сумма его хитов ниже, чем STALL_TICKS тиков назад (попадание с полным лечением в тот же
        // тик — не прогресс: стрелок россыпи с трёх клеток попадал, лечился, и «обмен уронами» сбрасывал простой);
        // простой — только когда добыча в досягаемости броска, а прогресса нет (на марше к врагу за 20+ клеток простоя
        // нет — стенд m3 army: пауза на подходе выключала давление, и обе армии простояли до конца)
        val now = getTicks()
        val enemyHitsNow = enemyCreeps.sumOf { it.hits }
        if (lastEnemyHitsTotal >= 0 && enemyHitsNow < lastEnemyHitsTotal) enemyDamageTaken += lastEnemyHitsTotal - enemyHitsNow
        lastEnemyHitsTotal = enemyHitsNow
        val ourHitsNow = army.sumOf { it.hits }
        enemyHitsHist.addLast(enemyHitsNow); ourHitsHist.addLast(ourHitsNow)
        while (enemyHitsHist.size > STALL_TICKS) enemyHitsHist.removeFirst()
        while (ourHitsHist.size > STALL_TICKS) ourHitsHist.removeFirst()
        // РАЗМЕН ЗА ОКНО ПОДНЯТ СЮДА (v221) из блока толчка: его слагаемые готовы уже здесь — наши потери копятся в
        // прологе, его строкой выше, — а читать окно нужно раньше, чем решаются бой по контакту и простой. Между
        // старым и новым местом окна не читал никто (`lostRaceNow()` зовётся из `runRunners`, до `runArmy`, и ниже
        // блока толчка; ранних выходов в этом отрезке нет), поэтому перенос без тумблера: дифф отчёта пуст побайтово
        val exchangeLedger = enemyDamageTaken - ourDamageTaken
        // ...и тот же размен ЗА ОКНО (v216, см. ledgerHist): срез берётся в одной точке тика, потому что
        // слагаемые обновляются в разных местах — наши потери в прологе, его в runArmy
        ledgerHist.addLast(exchangeLedger)
        ourLostHist.addLast(ourDamageTaken)
        hisLostHist.addLast(enemyDamageTaken)
        while (ledgerHist.size > LEDGER_WINDOW + 1) ledgerHist.removeFirst()
        while (ourLostHist.size > LEDGER_WINDOW + 1) ourLostHist.removeFirst()
        while (hisLostHist.size > LEDGER_WINDOW + 1) hisLostHist.removeFirst()
        ledgerWindow = if (ledgerHist.size >= 2) ledgerHist.last() - ledgerHist.first() else 0
        ourLostWindow = if (ourLostHist.size >= 2) ourLostHist.last() - ourLostHist.first() else 0
        hisLostWindow = if (hisLostHist.size >= 2) hisLostHist.last() - hisLostHist.first() else 0
        // РАЗМЕН ИДЁТ (v221, см. USE_FIGHT_BY_LEDGER): за LEDGER_WINDOW тиков хоть одна сторона потеряла
        // STALL_DAMAGE хитов. Та же мера, что у клапана проигранной гонки (см. lostRaceNow) и у простоя
        // (netDamage), только по обеим половинам окна: новых чисел нет. Разбор двух рейтинговых серий по реплеям
        // обеих сторон делит ею забеги начисто: в проигранных армия 38 % тиков в постуре ANNIHILATE, и в 92 %
        // этих тиков размена нет вовсе, — это 35 % матча против 4 % в выигранных (v219: 24 % против 5 %)
        val exchangeLive = ourLostWindow >= STALL_DAMAGE || hisLostWindow >= STALL_DAMAGE
        exchangeLiveNow = exchangeLive
        // наступление окупается (см. PUSH_EXCHANGE); без окна — да (нечего мерить)
        val exchangePaying = ourHitsHist.size < STALL_TICKS ||
            (enemyHitsHist.first() - enemyHitsNow) >= (ourHitsHist.first() - ourHitsNow) * PUSH_EXCHANGE
        val mobileArmy = army.filter { canMove(it) && it.id !in keeperIds }
        // ...а командир видит ВСЁ поле, включая хранителей флагов: решение снять хранителя — его, а не следствие того,
        // что он невидим (v173, оператор). Держат флаг они по-прежнему сами, пока приказа нет
        val commandArmy = if (USE_ORDER_OVER_KEEPER) army.filter { canMove(it) } else mobileArmy
        val chasers = strikers.ifEmpty { mobileArmy }
        // кого вообще можно догнать (см. catchable): добивание по перевесу идёт только за ними, и по ним же считается
        // пикет простоя — поэтому охота посчитана здесь, до простоя
        val huntable = armedEnemies.filter { catchable(it, chasers) }
cpuMark("a.hunt")
        // его мили вплотную к нашим — поднято сюда из блока постуры (v221, перенос без тумблера): читать его нужно и
        // прибору погони ниже, а между старым и новым местом он не менялся и не читался
        val meleeAdjacent = combatEnemies.any { e -> hasMelee(e) && army.any { getRange(e, it) <= 1 } }
        // ПАРА К ПОГОНЕ ЗА КАЙТЕРОМ (v221, только прибор; см. kchaseTicks). Разбор v220, матч с ●ω<♥♪#1: он не взял ни
        // одного флага за 700 тиков, мы 300 тиков гнались за его отходящей линией в постуре ANNIHILATE и легли 12 → 0,
        // а вето безфлагового броска отказало захвату 3329 раз. Простой «держит дистанцию» против него не наступает:
        // любой его выстрел даёт netDamage, и простой гаснет. Прибор считает тики, где погоня идёт в ОДНУ сторону —
        // за окно мы потеряли STALL_DAMAGE, он меньше нас, его центр от нас уходит, его мили не вплотную. Считается ДО
        // простоя и по тем величинам, какими простой читал бы её: постура и история дистанции — прошлого тика
        val kiteChaseNow = posture == Posture.ANNIHILATE && ourLostWindow >= STALL_DAMAGE && ledgerWindow < 0 && !meleeAdjacent &&
            enemyDistHist.size >= 2 && enemyDistHist.last() > enemyDistHist.first()
        kiteChaseSeen = kiteChaseNow
        if (posture == Posture.ANNIHILATE) { kchaseAnn++; if (kiteChaseNow) kchaseTicks++ }
        // с обеих сторон: бьют только нас — бой, не простой (матч 20, t=117)
        val netDamage = enemyHitsHist.size == STALL_TICKS &&
            (enemyHitsHist.first() - enemyHitsNow >= STALL_DAMAGE || ourHitsHist.first() - ourHitsNow >= STALL_DAMAGE)
        if (netDamage) stallUntil = 0
        // пикет в досягаемости броска все STALL_TICKS подряд (см. STALL_PICKET): армия, только что вошедшая в
        // досягаемость, простоя не даёт (матч 20, t=64). Считается пикет по ДОГОНЯЕМЫМ (см. catchable): прежде
        // «не больше STALL_PICKET вооружённых» отделяло пикет от армии по ЧИСЛУ, и блоб, который от нас уклоняется и
        // не дерётся, одним своим числом отменял простой — армия гналась за ним весь матч. Живой матч 26: huntable=0/8,
        // 902 хита урона за 1500 тиков с обеих сторон, ни одной смерти, проигрыш 12721:23408; стенд farm на карте 21:
        // три флага на одиннадцать очков в тик простояли ничьими 1500 тиков. Кого можем догнать — драка; кто
        // уклоняется — не повод стоять
        val nearArmed = armedEnemies.count { e -> strikers.any { getRange(it, e) <= ENGAGE_RANGE } }
        val nearCatchable = huntable.count { e -> strikers.any { getRange(it, e) <= ENGAGE_RANGE } }
        // пикет — МЕНЬШИНСТВО его вооружённых (v50, оператор по матчу 101: «загоняем врага в угол, а потом разворачиваемся и
        // уходим в центр, не добив»): загнанный в угол остаток из трёх-четырёх вооружённых с лекарями четыре раза за матч
        // считался пикетом («picket of 3 armed in reach for 20 ticks — flags until +300», t=161, 547, 895, 1256), и армия на
        // триста тиков уходила за флагами. Когда в досягаемости не меньше половины его вооружённых, это его армия, а не пикет
        val picket = nearArmed >= 1 && nearCatchable <= STALL_PICKET && nearArmed * 2 < armedEnemies.size
        preyNearTicks = if (picket) preyNearTicks + 1 else 0
        // ВТОРОЙ вид простоя — марш, который не идёт. Пикет ловит бесплодную погоню, только пока добыча ближе
        // ENGAGE_RANGE; за этой чертой армия «гналась» и стояла, а простой не считался ни разу. Идущая погоня обязана
        // двигать центр вооружённой массы: за MARCH_STALL_TICKS тиков он не сдвинулся НИ НА КЛЕТКУ — это не марш.
        // Матч 25: добыча стояла в 11 клетках, ближе никого, армия 990 тиков дёргалась на месте у (46,34); за весь
        // матч ни одного урона ни с одной стороны, и проигрыш по очкам 19927:24205 при 12 против 13 в тик
        val marchCell = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army })?.let { it.x * 100 + it.y } ?: -1
        marchHist.addLast(marchCell)
        // ТРЕТИЙ вид простоя — враг, который держит дистанцию: в добивании без контакта дистанция между центрами армий за
        // CHASE_WINDOW тиков не сократилась, и враг дальше броска. Матч 48 (けろびー v5, фермер): он взял шесть флагов к 80-му
        // (сам на 0,75 мощи), парил в 10–28 клетках от нас и не дрался — за 1600 тиков ни одного выстрела с нашей стороны;
        // пикет не срабатывал (враг дальше ENGAGE_RANGE), марш не «стоял» (армия за ним ходила), и ANNIHILATE держал армию
        // лицом к нему на двух-трёх флагах против его пяти: 8 в тик против 17, проигрыш 15652:22950 при 16000/16000 у обоих
        // застой по ближайшей группе (v132, USE_STALL_NEAREST_GROUP): центр его группы, ближайшей к нашему вооружённому центру
        val ourArmedCentroid = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army })
        val stallCentroid: Position? = if (USE_STALL_NEAREST_GROUP && ourArmedCentroid != null && armedEnemies.isNotEmpty()) {
            val nearest = armedEnemies.minByOrNull { getRange(it, ourArmedCentroid) }!!
            centroidOf(armedEnemies.filter { getRange(it, nearest) <= ENGAGE_RANGE })
        } else ctx.enemyCentroid
        val armyDist = stallCentroid?.let { getRange(ourArmedCentroid ?: it, it) } ?: -1
        // бой — контакт С ОБМЕНОМ (v74, см. USE_COLD_CONTACT): выстрел наш или удар по нам не дальше STALL_TICKS назад
        val exchangeRecent = now - lastFireTick <= STALL_TICKS || (lastHurtTick > 0 && now - lastHurtTick <= STALL_TICKS)
        val fightOn = inContact(armedEnemies, army) && (!USE_COLD_CONTACT || exchangeRecent)
        val pauseReach = if (USE_CHASE_WINDOW_WIDE) 2 * ENGAGE_RANGE else ENGAGE_RANGE + RANGED_RANGE   // v106: окно сквозь мигание
        val pausedChase = USE_CHASE_WINDOW_HOLD && posture == Posture.HOLD && (huntable.isEmpty() || USE_CHASE_WINDOW_ANY_HUNTABLE) &&
            armedEnemies.any { e -> army.any { getRange(e, it) <= pauseReach } }
        if ((posture == Posture.ANNIHILATE || pausedChase) && !fightOn && armyDist >= 0) {
            armyDistHist.addLast(armyDist)
            // центр ВООРУЖЁННЫХ (v58): центр всех его крипов двигали два бегающих скаута, и стоящий на D5 лагерь «уходил» —
            // отряд на 566-м при his_moved=0 по реплею (матч 133, одиннадцатый проигрыш фермеру-лагерю 8346:22771)
            enemyCentHist.addLast((if (USE_STALL_NEAREST_GROUP) stallCentroid else centroidOf(armedEnemies))?.let { it.x * 100 + it.y } ?: -1)
        } else { armyDistHist.clear(); enemyCentHist.clear() }
        while (armyDistHist.size > DETACH_WINDOW + 1) armyDistHist.removeFirst()
        while (enemyCentHist.size > DETACH_WINDOW + 1) enemyCentHist.removeFirst()
        // ...и это ОН уходит (v57): центр его вооружённых за окно сместился не меньше чем на четверть окна — стоячий лагерь, у
        // которого замираем мы, дистанцию не «держит». Окно отряда — DETACH_WINDOW (v59): по восьми тикам (CHASE_WINDOW) отряд
        // собрался на 207-м тике матча 139, когда дистанция за сто тиков сократилась с 40 до 12 — армия почти догнала, а
        // восьмитиковое окно поймало паузу; ядро без пяти встало, он ушёл и запарковался (3174:22931)
        fun kept(window: Int, needMoved: Boolean = true): Boolean {
            if (armyDistHist.size <= window || enemyCentHist.size <= window) return false
            val d0 = armyDistHist.elementAt(armyDistHist.size - 1 - window)
            val a = enemyCentHist.elementAt(enemyCentHist.size - 1 - window); val b = enemyCentHist.last()
            if (a < 0 || b < 0) return false
            val moved = maxOf(abs(a / 100 - b / 100), abs(a % 100 - b % 100))
            return armyDistHist.last() >= d0 && armyDistHist.last() > ENGAGE_RANGE && (!needMoved || moved >= window / 4)
        }
        val distanceKept = combatEnemies.isNotEmpty() && kept(DETACH_WINDOW)
        if (distanceKept) lastDistanceKeptTick = now
        // для простоя — и без его сдвига (v98, USE_KEEPS_DISTANCE_ANY_MOVE): застенчивый блоб держит дистанцию шагами на 2–3
        // загнанная группа в досягаемости (см. USE_STALL_CORNERED_GROUP): неподвижная группа его вооружённых не меньше SPLIT_MIN,
        // хотя бы один в досягаемости ударников, слабее их в PUSH_RATIO — застой «держит дистанцию» не наступает
        val corneredInReach = USE_STALL_CORNERED_GROUP && armedEnemies.size >= SPLIT_MIN && run {
            val still = armedEnemies.filter { e ->
                val h = enemyCellHist[e.id]
                h != null && h.size >= CHASE_WINDOW && maxOf(abs(h.first() / 100 - h.last() / 100), abs(h.first() % 100 - h.last() % 100)) <= 1
            }
            val group = still.filter { e -> still.count { getRange(e, it) <= ENGAGE_RANGE } >= SPLIT_MIN }
            group.isNotEmpty() && group.any { e -> chasers.any { getRange(it, e) <= ENGAGE_RANGE + RANGED_RANGE } } &&
                ourPowerOf(chasers, group) >= enemyPowerOf(group, chasers) * PUSH_RATIO
        }
        // залипание (v134, см. USE_CORNERED_STICKY): условие сидит на границе и в матче 6a9fa6ad переключалось 154 раза,
        // а вместе с ним и keepsDistance — армии на чётных тиках говорили «стой», на нечётных «иди»
        if (corneredInReach) corneredUntil = now + CORNERED_STICK
        val cornered = corneredInReach || (USE_CORNERED_STICKY && now < corneredUntil)
        if (DEBUG_LOG && cornered != corneredWas) println("cornered t=$now: ${if (cornered) "a still weak group of his in reach — no distance stall" else "gone"}")
        corneredWas = cornered
        val keepsDistance = !cornered && ((USE_KEEPS_DISTANCE_STALL && combatEnemies.isNotEmpty() && kept(CHASE_WINDOW)) ||
            (USE_KEEPS_DISTANCE_STALL_WINDOW && (distanceKept || (USE_KEEPS_DISTANCE_ANY_MOVE && combatEnemies.isNotEmpty() && kept(DETACH_WINDOW, needMoved = false)))))
        while (marchHist.size > MARCH_STALL_TICKS) marchHist.removeFirst()
        // в контакте стоять — законно (строй рубится на месте), и полное взаимное лечение даёт нулевой чистый урон
        val marchStalled = pushing && marchCell >= 0 && marchHist.size == MARCH_STALL_TICKS &&
            marchHist.all { it == marchCell } && !fightOn
        // сухой толчок (v86): толчок PASSIVE_TICKS без нашего выстрела и без удара по нам — не толчок
        val dryPush = USE_DRY_PUSH_STALL && pushing && lastFireTick >= 0 && now - lastFireTick >= PASSIVE_TICKS &&
            now - lastHurtTick >= PASSIVE_TICKS && !fightOn
        // в любой постуре, кроме отхода и уклонения: в ПОСТУ с висящим рядом врагом «держим линию» без простоя длилось до
        // конца матча (стенд m19 spread, t=600–1600)
        // боевые враги нужны ПИКЕТУ (он из них и состоит), а простою марша — нет: зачистка идёт ровно тогда, когда
        // боевых не осталось, и там сетка не сработала ни разу (стенд m18 roost: 1500 тиков погони за двумя скаутами)
        // ...И В ОТХОДЕ ТОЖЕ (v217). Оговорка «в любой постуре, кроме отхода и уклонения» стояла без своего
        // замера, а следствие у неё было тяжёлое: `!stalled` — единственный оставшийся выключатель
        // `contactFight`, поэтому после объявления отхода выйти из него было нельзя по построению, и счёт
        // оставался нулём при живых двенадцати крипах (живой замер v216: `objnone` даёт annihilate:179-207 при
        // постуре RETREAT). Условие `!netDamage` остаётся и само по себе узко: под огнём простой не объявляется,
        // так что правка касается ровно тихого отхода — того, из которого и надо уметь выйти
        if ((USE_STALL_IN_RETREAT || (posture != Posture.RETREAT && posture != Posture.EVADE)) && !netDamage && now >= stallUntil &&
            ((combatEnemies.isNotEmpty() && preyNearTicks >= STALL_TICKS) || marchStalled || keepsDistance || dryPush)) {
            stallUntil = now + STALL_COOLDOWN
            if (DEBUG_LOG) println("stall t=$now: ${if (dryPush && !marchStalled) "the push has fired nothing for $PASSIVE_TICKS ticks" else if (marchStalled) "the march has not moved a cell for $MARCH_STALL_TICKS ticks" else if (keepsDistance) "the enemy keeps its distance (${armyDistHist.first()} -> ${armyDistHist.last()} over $CHASE_WINDOW ticks)" else "picket of $nearArmed armed in reach for $preyNearTicks ticks"} without damage either way — flags until $stallUntil")
        }
        val stalled = now < stallUntil
        stalledNow = stalled

        // ---- постура ----
        val ours = ourPowerOf(army, combatEnemies)
        val theirs = enemyPowerOf(combatEnemies, army)
        // РЕЖИМ ВЫЖИВАНИЯ (v223, доктрина оператора, см. USE_SURVIVAL): ведём по очкам, а его армия сильнее — не деремся,
        // а уходим, беря флаги с выходом. Порог и гистерезис — как у «слабее», по мощи всей армии
        val leadingNow = ourScore > enemyScore
        if (leadingNow && armedEnemies.isNotEmpty()) survLead++
        surviving = USE_SURVIVAL && leadingNow && armedEnemies.isNotEmpty() && theirs > 0.0 &&
            theirs >= ours * (if (surviving) RETREAT_RELEASE_RATIO else RETREAT_RATIO)
        if (surviving) survTicks++
        theirsHist.addLast(theirs)
        while (theirsHist.size > MEASURE_WINDOW) theirsHist.removeFirst()
        // множители окна (v114): его мощь сейчас → его сильнейшая и слабейшая за окно; при нулевой мере — 1
        val theirsUp = if (USE_CORE_MEASURE_WINDOW && theirs > 0.0) (theirsHist.maxOrNull() ?: theirs) / theirs else 1.0
        val theirsDown = if (USE_CORE_MEASURE_WINDOW && theirs > 0.0) (theirsHist.minOrNull() ?: theirs) / theirs else 1.0
        val nearRange = if (posture == Posture.RETREAT) NEAR_RANGE + NEAR_RELEASE else NEAR_RANGE
        // ОТВЕРГНУТО стендом: «враг рядом — рядом с МАССОЙ армии, а не с любым нашим крипом» (хранители стоят по
        // одному на разных концах карты, и висящий у хранителя враг россыпи отменяет цель-флаг у всей армии).
        // Целевой сценарий m22 spread не сдвинулся вовсе (16622:24323), а m20 spread перешёл из победы в проигрыш
        // (24337:21666 -> 19400:24328) и m19 block из уничтожения армии врага на 389-м в победу по очкам на 1142-м;
        // выиграли только россыпи на 12, 19 и 21. Мигание постуры на россыпи — открытая находка
        val enemyNear = armedEnemies.any { e -> army.any { getRange(e, it) <= nearRange } }
        // контакт решает сам: пассивного поста в контакте нет — он отдаёт армию по одному (стенд rush: десять
        // за двоих). Отход из контакта возможен, только если он не бегство: никто из врагов-мили не вплотную
        // и наш строй не медленнее их самого быстрого — при равной скорости преследователь стреляет в спину
        // каждый тик, а обездвиженные остаются врагу (стенд rush: отход при 1250 против 1619 отдал ещё
        // шестерых). Иначе в контакте — бой всем составом, даже слабее: рубка с фокусом лучше разгрома
        // контакт армии — контакт её МАССЫ (см. MASS_RANGE): один оторвавшийся не переводит армию в бой
        val massCentroid = clusterCentroid(army.filter { hasWeapon(it) }.ifEmpty { army }) ?: ctx.ourCentroid
        val massArmy = army.filter { getRange(it, massCentroid) <= MASS_RANGE }.ifEmpty { army }
        val contact = inContact(armedEnemies, massArmy)
        // ИДЁТ ЛИ БОЙ (v215): контакт по МАССЕ армии либо размен за последние STALL_TICKS тиков. Считается
        // здесь, ВЫШЕ отряда и командирской гонки, — оба механизма разделения читают его этим тиком, а не
        // прошлым (порядок тика: runRunners идёт раньше runArmy, и признак, посчитанный ниже, опаздывал бы)
        fightOnNow = contact || exchangeRecent
        // ПАРА К ОТЗЫВУ ПО РАЗМЕНУ (v221, только прибор): сколько тиков «бой идёт» держится на одном слове
        // «контакт» — ни одна сторона за окно не потеряла STALL_DAMAGE. Читать вместе с recall= и budget=
        if (fightOnNow) { warmFightAll++; if (!exchangeLive) warmFight++ }
        // ПРИЗНАК ОТХОДА СЧИТАЕТСЯ ЗДЕСЬ (v217, см. USE_BREAK_OFF_HOLDS_LINE): он должен успеть погасить
        // наступление, а `pushing` решается на триста строк ниже. Величины готовы: контакт уже есть, а
        // `ourDamageTaken`/`enemyDamageTaken` копятся с начала матча
        val outmatchedNow = USE_COMMAND_BREAKS_OFF && contact && armedEnemies.isNotEmpty() &&
            ourDamageTaken > 0 && enemyDamageTaken < ourDamageTaken * BREAK_OFF_RATIO
        outmatchedTicks = if (outmatchedNow) outmatchedTicks + 1 else 0
        val breakOffNow = outmatchedTicks >= BREAK_OFF_TICKS
        // ОТЗЫВ (v215, см. USE_NO_SPLIT_IN_FIGHT): едва бой начался, отпущенные возвращаются в кулак. Очистка стоит
        // ЗДЕСЬ, а не внутри `commandRace`: выйдя из режима гонки, командир эту функцию не зовёт вовсе, и `cmdDetach`
        // оставался с прошлого тика — отпущенные не возвращались никогда
        if (USE_NO_SPLIT_IN_FIGHT && fightOnNow) {
            fightTicksNow++
            recalled += cmdDetach.size + detachedIds.size
            cmdDetach.clear()
            detachedIds.clear()
        }
        val ourPeriod = mobileArmy.maxOfOrNull { plainPeriod(it) } ?: 1
        val theirPeriod = combatEnemies.filter { canMove(it) }.minOfOrNull { plainPeriod(it) } ?: Int.MAX_VALUE / 4
        // при РАВНОЙ скорости отход из контакта без мили вплотную — размен выстрелами в обе стороны, не бегство; из
        // точки отхода, куда уже пришли, отходить некуда — бой (матч 5: семеро в углу (3,96) при «отходе» не
        // шевелились и не били, пока их расстреливали с трёх клеток)
        val atRetreatPoint = retreatTarget?.let { getRange(ctx.ourCentroid, it) <= POST_STANDOFF + ARRIVED_SLACK } ?: false
        // из контакта отхода нет: «отход, пока мили не вплотную» мигал ДОБИТЬ/ОТХОД через тик и отдавал армию по одному
        // в матчах 4, 6 и 7 (в седьмом — при 1.53, без единой потери у врага); при равной скорости из контакта не
        // уйти, и единственный способ его кончить — бой строем
        // без стрелков строя нет — лекарей и раненых травят, и «в контакте держим строй» держало их у поста, где
        // стоял враг (стенд m7 sleeper: три лекаря с flee=true разбежались по карте и были добиты поодиночке)
        val retreatFeasible = (!contact || strikers.isEmpty()) && !atRetreatPoint
cpuMark("a.retreat")
        // мера боя (v120, см. USE_FIGHT_PACK_MEASURE): его боевые по порядку прихода к нашей массе — первый и все, кто придёт,
        // пока стая, набранная до него, умирает под нашим огнём (окно растёт вместе со стаей: колонна входит целиком)
        val fightPack = if (!USE_FIGHT_PACK_MEASURE || combatEnemies.size <= 1 || strikers.isEmpty()) combatEnemies else run {
            // центр массы в стене даёт пустое поле (см. passableNear): все приходы MAX, стая — вся армия, и уклонение в угол
            // на 199-м тике split m28 при его шестёрке в шести клетках
            val flow = flowTo(ctx, passableNear(massCentroid))
            val arrival = combatEnemies.map { e -> e to pathTicks(e, flow, e.x * 100 + e.y) }.sortedBy { it.second }
            val pack = ArrayList<Creep>()
            val t0 = arrival.first().second
            var limit = t0
            for ((e, t) in arrival) {
                if (pack.isNotEmpty() && t > limit) break
                pack.add(e)
                val kill = fightTicks(pack, strikers)
                limit = if (kill >= Int.MAX_VALUE / 4) Int.MAX_VALUE / 2 else t0 + kill
            }
            pack
        }
        fightPackIds = fightPack.mapTo(HashSet()) { it.id }
        val fightAll = fightPack.size == combatEnemies.size
        val oursFight = if (fightAll) ours else ourPowerOf(army, fightPack)
        val theirsFight = if (fightAll) theirs else enemyPowerOf(fightPack, army)
        // стая НАСТУПЛЕНИЯ (v120, USE_PUSH_PACK_AT_HEAD): наступать — идти к его ближайшему, и бой будет у НЕГО, а не у нашей
        // массы: стая — те, кто дойдёт до головы не позже нас плюс время её смерти. Хвост колонны в десяти клетках за головой
        // приходит к ней через десять тиков после нас — он в стае; вторая группа фермера в другом углу — нет. Мера прихода
        // к нашей массе (fightPack) годится для «слабее» (стоим — кто дойдёт до нас), но для толчка она считала голову
        // колонны без хвоста: таблица входов v117 → v120g brawl 4 хуже / 1 лучше (m30 +50: 2536 → 6250 своих хитов, 13 → 9 живых)
        val pushPack = if (!USE_FIGHT_PACK_MEASURE || !USE_PUSH_PACK_AT_HEAD || combatEnemies.size <= 1 || strikers.isEmpty()) fightPack else run {
            val head = combatEnemies.minByOrNull { e -> massArmy.minOf { getRange(e, it) } } ?: return@run fightPack
            val toHead = flowTo(ctx, head)
            val ourTravel = strikers.map { pathTicks(it, toHead, it.x * 100 + it.y) }.filter { it < Int.MAX_VALUE / 4 }.maxOrNull() ?: return@run fightPack
            val arrival = combatEnemies.map { e -> e to (if (e.id == head.id) 0 else pathTicks(e, toHead, e.x * 100 + e.y)) }.sortedBy { it.second }
            val pack = ArrayList<Creep>()
            var limit = ourTravel
            for ((e, t) in arrival) {
                if (pack.isNotEmpty() && t > limit) break
                pack.add(e)
                val kill = fightTicks(pack, strikers)
                limit = if (kill >= Int.MAX_VALUE / 4) Int.MAX_VALUE / 2 else ourTravel + kill
            }
            pack
        }
        val pushAll = pushPack.size == combatEnemies.size
        val oursPush = if (pushAll) ours else ourPowerOf(army, pushPack)
        val theirsPush = if (pushAll) theirs else enemyPowerOf(pushPack, army)
        val weaker = theirsFight >= oursFight * (if (posture == Posture.RETREAT) RETREAT_RELEASE_RATIO else RETREAT_RATIO)
        // из идущего боя (см. RETREAT_CONTACT_RATIO) — только при явном проигрыше
        // ⚠️ Здесь жил `weakerContact` — и после снятия вакуумной охраны в `contactFight` он остался
        // объявленным и никем не читаемым. Снят вместе с ней (v217); вместе с ним осиротела и константа
        // RETREAT_CONTACT_RATIO, которая существовала только ради него
        // ДОБИТЬ по перевесу — с гистерезисом; по контакту — пока контакт есть (без гистерезиса: см. PUSH_RELEASE_RATIO)
        val stalemate = behindTicks >= BEHIND_PATIENCE
        stalemateNow = stalemate
        val holdingFlag = USE_PUSH_KEEPS_FLAG && USE_HOLD_OWN_FLAG && !fightOn &&
            ctx.flags.any { it.ours && getRange(it.pos, ctx.ourCentroid) <= POST_STANDOFF }
        // (размен матча и размен за окно считаются выше, у историй хитов — перенесены в v221, см. exchangeLive)
        // нулевой ледж (обмена ещё не было) допуск не закрывает — иначе толчок в стоящий лагерь стенда не начинался
        // (v87b: spread m33 24314 → 7298, 14 хуже); закрывает только проигранный размен
        val ledgerOk = !USE_PUSH_LEDGER || exchangeLedger >= 0
        // в проигранной гонке свой флаг порога не поднимает (v99, USE_PUSH_KEEPS_FLAG_UNLESS_LOST)
        val flagRaises = holdingFlag && !(USE_PUSH_KEEPS_FLAG_UNLESS_LOST && lostRaceNow())
        val pushRatio = if (flagRaises || !ledgerOk) PUSH_RATIO else if (stalemate) PUSH_RATIO_STALEMATE else if (behindOnScore) PUSH_RATIO_BEHIND else PUSH_RATIO
        val pushRelease = if (stalemate) PUSH_RELEASE_RATIO_STALEMATE else if (behindOnScore) PUSH_RELEASE_RATIO_BEHIND else PUSH_RELEASE_RATIO
        // зачистка: у врага не осталось никого с боем, а мы позади по очкам — аннигиляция единственная победа, и остаток
        // (скауты, обломки) добивается без оглядки на «ловимость» (матч 19: последний M1 с 28 хитами сидел у нашего R3
        // пятьсот тиков, армия ходила за флагами и проиграла по очкам)
        val sweep = combatEnemies.isEmpty() && enemyCreeps.isNotEmpty() && strikers.isNotEmpty() && behindOnScore
        // и зачистка уступает простою: она стояла ВНЕ него, поэтому замерший на месте «дожим» не выключался ничем
        // перехват (см. USE_INTERCEPT): ближайший к центру фермера флаг не из его — туда; свой — пост (см. post ниже); считается до наступления — см. chaseVeto, иначе — цель
        val interceptFlag: FlagInfo? = if (!enemyNotFightingNow || armedEnemies.isEmpty()) null else ctx.enemyCentroid?.let { ec ->
            val group = strikers.ifEmpty { mobileArmy }
            // липкий: выбранный держим, пока он не его
            interceptFlagId?.let { id -> ctx.flags.firstOrNull { it.id == id && !it.theirs } }
                ?: ctx.flags.filter { !it.theirs }.sortedBy { getRange(it.pos, ec) }.firstOrNull { f ->
                    val flow = flowTo(ctx, f.pos)
                    val ours = group.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: 0
                    ours < Int.MAX_VALUE / 4 && ours + INTERCEPT_MARGIN <= getRange(f.pos, ec)
                }
        }
        interceptFlagId = interceptFlag?.id
        // перехват снимает наступление, только пока есть ЧТО перехватывать — флаг не наш, за которым фермер придёт; когда все
        // флаги его, «перехват» — пост у своего флага, а за ним он не придёт при 22 очках в тик. Матч 70 (けろびー v5): он сел
        // на D5 двенадцатью при 0,6 мощи (2954 против наших 4179), и армия 1000 тиков дёргалась в 10–13 клетках от него между
        // ДОБИТЬ и постом в 35 клетках позади (noFire ≥ 20 и «в досягаемости броска» мигали на границе 8 клеток, поза
        // переключалась каждые 1–4 тика) — 3174:22934 без единого выстрела с обеих сторон. Позади по очкам против врага,
        // который не дерётся и которому нечего перехватывать, стоять — проиграть наверняка; впереди — стоять верно (v42)
        // отряды (см. USE_DETACH): решение на следующий тик — Ctx строится до мощей
        if (USE_DETACH) {
            // фермер: сто тиков (PASSIVE_TICKS) без единого снятого с нас хита с тех пор, как он последний раз был в досягаемости
            // броска, и был в ней не дальше ста тиков назад. Счётчик «рядом и не стреляет» по тикам (noFireTicks) сбрасывался
            // всякий раз, когда блоб отходил дальше NEAR_RANGE, и за 1800 тиков матча 108 не дошёл до ста ни разу (0 detached)
            // погоня без сближения (v57, см. lastDistanceKeptTick) не дальше PASSIVE_TICKS назад — вход; собранный отряд держится,
            // пока его вооружённые есть. Фермер — тот, кто НИ РАЗУ не ударил (lastHurtTick == 0): «сто тиков без удара» пускало
            // отряд против кайтера стенда, который бил на 76–84-м приманкой и вернулся за разделённым ядром — m31 kite 1817:23890,
            // армия стёрта к 400-му (ядро без четырёх стрелков против пяти его стрелков с лекарями: урон мили, которых кайтер не
            // подпускает, в паритете по Ланчестеру считается полностью), m28 kite при наборе из мили — 4970:23907. Живой фермер
            // (матчи 119, 126) не ударил ни разу за 1300–1600 тиков. Первый удар отзывает отряд навсегда
            val chaseDry = now - lastDistanceKeptTick <= PASSIVE_TICKS
            val quiet = lastHurtTick == 0 || now - lastHurtTick >= FARMER_QUIET   // тишина (v65, см. FARMER_QUIET)
            // второй вход (v68): противник тих FARMER_QUIET с ПЕРВОЙ досягаемости (бросок на сотом тике — не фермер) и гонка проиграна
            // (отстаём с меньшим темпом) — отряд собирается без сухой погони. Матч 161 (шестнадцатый проигрыш фермеру 19771:23843):
            // отряд вышел на 806-м, когда толчок наконец не сближал, и с 900-го мы вели 14 против 11 в тик, а 800 тиков до того
            // были проиграны 3–13 против 12–22 — качели «взяли флаги → слабее → уклонение → потеряли → сильнее → толчок»
            val quietSinceFirstReach = firstNearTick >= 0 && now - firstNearTick >= FARMER_QUIET
            farmerQuietNow = quiet && quietSinceFirstReach
            val lostRaceNow = behindOnScore && ourRate <= enemyRate
            // сухая охота (v75, см. USE_DRY_HUNT): мы уже стреляли, с тех пор PASSIVE_TICKS ни выстрела, ни удара, отстаём — и его
            // вооружённые РАССЫПАНЫ: крупнейшая группа в ENGAGE_RANGE не больше половины (бегуны матча 183: 2 по одному). «Сто
            // тиков без обмена» само по себе (v75 первая проба) выпускало отряд на сотом тике против целого лагеря (счёт от
            // начала матча, m30 camp 18891:23756) и против кайтера стенда, ходящего впятером (m31 kite 1979:23896 — 25 тиков
            // отряда на 183–214-м, и бой без четверых проигран): гейт 120/125
            val largestGroup = armedEnemies.maxOfOrNull { e -> armedEnemies.count { getRange(e, it) <= ENGAGE_RANGE } } ?: 0
            val scatteredRaw = armedEnemies.isNotEmpty() && largestGroup <= maxOf(1, armedEnemies.size / 2)
            // с гистерезисом (v115): включается по «≤ половины», гаснет по сбору «≥ SCATTER_OFF_SHARE»
            val gathered = armedEnemies.isEmpty() || largestGroup * 4 >= armedEnemies.size * 3   // три четверти (SCATTER_OFF_SHARE)
            scatteredLatched = if (!USE_SCATTER_HYSTERESIS) scatteredRaw else if (scatteredRaw) true else if (gathered) false else scatteredLatched
            val scattered = scatteredLatched
            val groupSeed = armedEnemies.maxByOrNull { e -> armedEnemies.count { getRange(e, it) <= ENGAGE_RANGE } }
            val largestMembers = if (groupSeed == null) armedEnemies else armedEnemies.filter { getRange(groupSeed, it) <= ENGAGE_RANGE }
            // дебют-гонка (v91, см. USE_SCATTER_RACE): россыпь его армии до первого обмена
            // «мы ближе» — всей силой, с уже выпущенными бегунами (v120): бегун, выпущенный к свободному флагу, и был тем, кем мы
            // были ближе; без него гонка кончалась, его отзывали, а следующим тиком выпускали снова — 1260 строк detach за
            // матч (split m31), постура мигала с ним ДОБИТЬ↔ДЕРЖАТЬ через тик (наша мощь 4179↔3502)
            val raceForce = if (USE_RACE_FORCE_WITH_RUNNERS) army + ctx.runners.filter { it.id in detachedIds } else army
            // цель гонки — и флаг под стаей, которую бьёт ПАРА наших слабейших бегунов (v125, USE_RACE_PAIR_TARGETS): быстрый
            // гастролёр (けろびー#4, серия 327–346) оставляет на каждом взятом флаге одного хранителя, тот уходит от наших в шести и
            // возвращается — «свободных» флагов нет, гонка v91 молчала (targets=0), армия толкала его пятёрку 200 тиков, а его
            // хранители держали шесть флагов (стенд blitz: 4-4 при 1:6 к 200-му)
            val racePair = army.filter { hasWeapon(it) && fullSpeed(it) && it.id !in keeperIds && it.id !in rotatingIds }
                .sortedBy { ourPowerOf(listOf(it), emptyList()) }.take(2)
            fun pairBeats(f: FlagInfo): Boolean {
                if (racePair.size < 2) return false
                val pack = armedEnemies.filter { getRange(it, f.pos) <= ENGAGE_RANGE }
                return pack.isNotEmpty() && ourPowerOf(racePair, pack) >= enemyPowerOf(pack, racePair) * PUSH_RATIO
            }
            val raceFree = ctx.flags.filter { f -> !f.ours && armedEnemies.none { getRange(it, f.pos) <= ENGAGE_RANGE } &&
                (armedEnemies.minOfOrNull { getRange(it, f.pos) } ?: 999) > (raceForce.minOfOrNull { getRange(it, f.pos) } ?: 999) }
            val racePaired = if (USE_RACE_PAIR_TARGETS) ctx.flags.filter { f -> !f.ours && f.occupant?.my != true && pairBeats(f) } else emptyList()
            val raceTargets = raceFree.size + racePaired.size
            val raceSlots = raceFree.size + racePaired.size * 2   // по два бегуна на флаг под стаей (см. USE_RUNNER_PAIRS)
            // расколот (v119): ВТОРАЯ группа его вооружённых (вне крупнейшей, в ENGAGE_RANGE друг от друга) не меньше SPLIT_MIN —
            // две группы фермера, а не отставшие от колонны на марше: первый срез «двое вне крупнейшей» стартовал гонку на
            // двадцатом тике по хвосту колонны spread, и spread m19/m31/m33 из побед в 20403:24313, 14392:24330, 14990:24318
            val rest = armedEnemies.filter { e -> largestMembers.none { it.id == e.id } }
            val secondGroup = rest.maxOfOrNull { e -> rest.count { getRange(e, it) <= ENGAGE_RANGE } } ?: 0
            val splitGroups = USE_SPLIT_RACE && armedEnemies.size >= 4 && secondGroup >= SPLIT_MIN
            val raceNow = USE_SCATTER_RACE && (scattered || splitGroups) && armedEnemies.size >= 4 && raceTargets > 0
            if (posture == Posture.FLAG || posture == Posture.EVADE || posture == Posture.RETREAT) lastNonHuntTick = now
            // рассыпанный остаток — вход v75 как был; блоб-остаток — под стрелковой защитой пула и только после PASSIVE_TICKS
            // охоты без FLAG/EVADE/RETREAT («охота длилась» и для россыпи задерживала отряд: spread m33 24327:24222 → 19509:24315)
            val dryHunt = USE_DRY_HUNT && behindOnScore && lastFireTick >= 0 &&
                now - lastFireTick >= PASSIVE_TICKS && now - lastHurtTick >= PASSIVE_TICKS &&
                (scattered || (USE_DRY_HUNT_RANGED_GUARD && now - lastNonHuntTick >= PASSIVE_TICKS))
            fun rangedMass(cs: List<Creep>) = cs.sumOf { InfluenceMap.profileOf(it).ranged }
            val theirRangedMass = rangedMass(combatEnemies)
            val quietChain = quiet && (chaseDry || detachedIds.isNotEmpty() || (quietSinceFirstReach && lostRaceNow))
            // МИЛИ, КОТОРЫЙ НЕ ДОСТАЁТ, — НЕ АРМИЯ, А ОТРЯД (v194, USE_IDLE_MELEE_RUNS). Отряд набирается только против
            // соперника, помеченного `farmer`, а этот ярлык требует, чтобы он НЕ ДРАЛСЯ: `raceNow` хочет его россыпи,
            // `dryHunt` — тишины по огню и урону. Coldkimchi#2 дерётся и фармит флаги ОДНОВРЕМЕННО — держит плотный
            // блок в контакте (massed=true каждый тик) и отряжает 2–4 крипа за флагами, — и категории для такого у нас
            // нет. Замер по двенадцати играм v191: отряжённых бойцов ноль во ВСЕХ матчах, флаговый забег мы ведём
            // двумя разведчиками по сто хитов, и медиана скорости очков выходит 3 против его 15 к шестисотому тику;
            // пять поражений из двенадцати — это забег, проигранный в первой трети, при целой армии. Основание отряда
            // здесь не ярлык соперника, а НАША измеренная бесполезность: мили, за окно контакта ни разу не
            // дотянувшийся, в бою не участвует, и все пороги выпуска ниже считают его вклад по той же доле (v193)
            val meleeIdle = USE_IDLE_MELEE_RUNS && armedEnemies.isNotEmpty() && touchShare < TOUCH_MIN
            val farmer = armedEnemies.isNotEmpty() && ((firstNearTick >= 0 && (quietChain || dryHunt)) || raceNow || meleeIdle)
            val viaDryHunt = dryHunt && !quietChain   // отряд держится только сухой охотой (v82b)
            val viaRace = raceNow && !quietChain && !dryHunt   // отряд держится только дебют-гонкой (v91)
            val detachedBefore = detachedIds.size
            // отряд без дела (v84): все отделённые DETACH_WINDOW тиков подряд без цели — отзыв, и набор ждёт то же окно
            if (USE_DETACH_IDLE_RECALL && detachedIds.isNotEmpty() && detachedIds.all { it in idleRunnerIds }) idleDetachTicks++ else idleDetachTicks = 0
            if (USE_DETACH_IDLE_RECALL && idleDetachTicks >= DETACH_WINDOW) {
                if (DEBUG_LOG) println("detach t=$now: ${detachedIds.size} recalled — nothing for a runner to take for $DETACH_WINDOW ticks")
                detachedIds.clear(); idleDetachTicks = 0; detachRecallTick = now
            }
            // поштучно (v85): отделённый DETACH_WINDOW тиков подряд без цели возвращается в ядро
            if (USE_DETACH_IDLE_RECALL) {
                for (id in detachedIds) idleRunnerTicks[id] = if (id in idleRunnerIds) (idleRunnerTicks[id] ?: 0) + 1 else 0
                idleRunnerTicks.keys.retainAll { it in detachedIds }
                val idle = detachedIds.filter { (idleRunnerTicks[it] ?: 0) >= DETACH_WINDOW }
                if (idle.isNotEmpty()) {
                    if (DEBUG_LOG) println("detach t=$now: ${idle.size} of ${detachedIds.size} recalled — without a target for $DETACH_WINDOW ticks")
                    detachedIds.removeAll(idle.toSet()); idle.forEach { idleRunnerTicks.remove(it) }; detachRecallTick = now
                }
            }
            // ОДНА ОПОРА (v95b): группа врага и порог одни для выпуска, проверки с дебаффом цели и отзыва — при гонке выпуск
            // мерился против его крупнейшей группы, а отзыв против всей армии при 1,3, и трое выходили и возвращались на
            // следующий тик (m31 camp: 173/174, 255/256). Порог ядра в проигранной гонке НЕ опускается до порога захватов
            // (PARITY_FLOOR_LOST, v88): это исключение про захват стороной, а не про раскол ядра — с 0,75 для ядра пул против
            // пар spread отпускал лишних, и spread из 6/6 стал 2/6 (m28 24322:19608 → 14960:24320); при паритете выпуска с
            // дебаффом цели просто нет, а скауты берут при 0,75 как раньше
            val coreRef = if (viaRace) largestMembers else combatEnemies
            val coreFloor = if (viaDryHunt || viaRace) PUSH_RATIO else PARITY_FLOOR
            // при россыпи (v97, USE_SCATTER_RECALL_REF) опора ОТЗЫВА — его крупнейшая группа при PUSH_RATIO; выпуск — как был
            if (detachedIds.isEmpty()) scatteredAtRelease = scattered   // без отряда ярлык свежий; с отрядом — как при выпуске (v117)
            val recallGroup = viaRace || (USE_SCATTER_RECALL_REF && (if (USE_RECALL_REF_LATCH) scatteredAtRelease else scattered))
            val recallRef = if (recallGroup) largestMembers else combatEnemies
            val recallFloor = if (viaDryHunt || recallGroup) PUSH_RATIO else PARITY_FLOOR
            // одна мера ядра (v94): порог держится каждый тик — просело, сильнейший отделённый возвращается
            if (USE_ONE_CORE_MEASURE && farmer && detachedIds.isNotEmpty()) {
                val floorNow = recallFloor
                var core = army.filter { it.id !in detachedIds }
                var recalled = 0
                val short = core.any { hasWeapon(it) } && ourPowerOf(core, recallRef) < enemyPowerOf(recallRef, core) * theirsDown * floorNow
                coreShortTicks = if (short) coreShortTicks + 1 else 0
                val recallNow = !USE_RECALL_PERSIST || coreShortTicks >= RECALL_TICKS
                while (recallNow && detachedIds.isNotEmpty() && core.any { hasWeapon(it) } && ourPowerOf(core, recallRef) < enemyPowerOf(recallRef, core) * theirsDown * floorNow) {
                    val back = ctx.runners.filter { it.id in detachedIds }.maxByOrNull { ourPowerOf(listOf(it), emptyList()) } ?: break
                    detachedIds.remove(back.id); core = core + back; recalled++
                }
                if (recalled > 0) { detachRecallTick = now; coreShortTicks = 0 }   // новый выпуск ждёт DETACH_WINDOW, как после отзыва «без цели» — иначе качели
                if (DEBUG_LOG && recalled > 0) println("detach t=$now: $recalled recalled — the core fell under ${floorNow} of him by the posture's measure")
            }
            farmerOffTicks = if (farmer) 0 else farmerOffTicks + 1
            // сброс отряда по «не фермер» — только продержавшись FARMER_OFF_TICKS (v115): одноткового моргания признака не хватает
            if (!farmer) { if (farmerOffTicks >= FARMER_OFF_TICKS) detachedIds.clear() }
            // ...и ОТПУСКАЕТ ЛИ ОТРЯД — решает командир (v164): механика выпуска проверена годом замеров и остаётся, но
            // включает её его режим, а не собственные условия. Полная замена командирской раздачей отвергнута замером:
            // 133 из 135 (roost 7 615:24 325, camp 22 304:23 966) — прежняя логика знает и сухую охоту, и гонку, и
            // охрану стрелков, чего своя раздача не покрывает
            // ...и `meleeIdle` БОЛЬШЕ НЕ СНИМАЕТ ЗАЩИТУ (v215, см. USE_NO_SPLIT_IN_FIGHT). Он стоял оговоркой к
            // обеим половинам гейта — «командир в режиме боя» и «мы в контакте», — и снимал их обе. Смысл был
            // «мили всё равно не дерутся, пусть идут за флагами», а следствие — отряд набирался посреди рубки
            // ровно тогда, когда наши мили не дотягивались, то есть по первой же жалобе оператора
            else if ((if (USE_NO_SPLIT_IN_FIGHT) !fightOnNow
                      else ((!USE_COMMAND_OWNS_DETACH || cmdMode != CmdMode.FIGHT) || meleeIdle) &&
                          ((!contact || (USE_COLD_CONTACT && !exchangeRecent)) || meleeIdle)) &&
                (!USE_DETACH_IDLE_RECALL || now - detachRecallTick >= DETACH_WINDOW)) {
                val armed = army.filter { hasWeapon(it) && fullSpeed(it) && it.id !in keeperIds && it.id !in rotatingIds }
                // столько, сколько требуют охраны целей (v94): флаг с его вооружённым в ENGAGE_RANGE — двоих, без — одного
                val unmanned = if (USE_RUNNER_PAIRS) ctx.flags.sumOf { f -> if (f.occupant?.my == true) 0 else if (armedEnemies.any { getRange(it, f.pos) <= ENGAGE_RANGE }) 2 else 1 }
                    else ctx.flags.count { f -> f.occupant?.my != true }
                val pool = if (USE_DRY_HUNT_MELEE_FIRST && (viaDryHunt || viaRace || meleeIdle)) armed.sortedWith(compareBy({ InfluenceMap.profileOf(it).ranged }, { ourPowerOf(listOf(it), emptyList()) }))
                    else armed.sortedBy { ourPowerOf(listOf(it), emptyList()) }
                var remaining = army.filter { it.id !in detachedIds }
                for (c in pool) {
                    if (detachedIds.size >= unmanned) break
                    if (viaRace && detachedIds.size >= raceSlots) break   // гонка — за неохраняемые и за флаги под стаей по силам паре (v91, v125)
                    val without = remaining.filter { it.id != c.id }
                    // без тишины (сухая охота) ядро держит охотничий перевес, не паритет
                    // его мощь — против ядра-кандидата, не против полной армии (v84: пары Ланчестера)
                    // в дебют-гонке (v91) ядро мерится против его крупнейшей группы: россыпь армией не дерётся
                    val theirsVsCore = (if (USE_DETACH_PAIRED_MEASURE || viaRace) enemyPowerOf(coreRef, without) else theirs) * theirsUp
                    if (without.none { hasWeapon(it) } || ourPowerOf(without, coreRef) < theirsVsCore * coreFloor) break
                    // сухая охота без россыпи — стрелковая масса ядра держит перевес над его стрелками (v82, кайтер)
                    if (viaDryHunt && !scattered && USE_DRY_HUNT_RANGED_GUARD && rangedMass(without) < theirRangedMass * PUSH_RATIO) break
                    // гонка (см. USE_RACE_RANGED_GUARD): стрелок не отпускается, пока стрелков в ядре меньше, чем у его крупнейшей группы × PUSH_RATIO
                    if (USE_RACE_RANGED_GUARD && raceNow && InfluenceMap.profileOf(c).ranged > 0.0 && rangedMass(without) < rangedMass(largestMembers) * PUSH_RATIO) break
                    // компактная крупнейшая группа (см. USE_RANGED_GUARD_COMPACT): та же защита на любой цепочке
                    // ...первый срез «крупнейшая группа не меньше COMPACT_MIN» ОТВЕРГНУТ: split 6-2 → 4-4 (m28 24 307:20 109 → 18 643:24 298, m32
                    // 24 291:20 558 → 23 651:24 298) — расколотый фермер (6–7 из 13 в группе) обгоняет нас по флагам, когда стрелки не бегут;
                    // второй срез: компактная = не меньше двух третей его вооружённых в одной группе (けろびー#4: 11 из 11)
                    if (USE_RANGED_GUARD_COMPACT && largestMembers.size >= COMPACT_MIN && largestMembers.size * 3 >= armedEnemies.size * 2 && InfluenceMap.profileOf(c).ranged > 0.0 && rangedMass(without) < rangedMass(largestMembers) * PUSH_RATIO) break
                    // выпуск с дебаффом цели (v95): ядро без крипа и с дебаффом флага, за которым он пойдёт, держит тот же порог
                    if (USE_RELEASE_WITH_TARGET_DEBUFF) {
                        val target = ctx.flags.filter { !it.ours && it.occupant?.my != true }
                            .minByOrNull { f -> getRange(c, f.pos) + (if (armedEnemies.any { getRange(it, f.pos) <= ENGAGE_RANGE }) 100 else 0) }
                        if (target != null) {
                            val (oursAfter, theirsAfter) = powerAfterFor(ctx, without, coreRef, target)
                            if (oursAfter < theirsAfter * coreFloor) break
                        }
                    }
                    detachedIds.add(c.id)
                    splitAll++; if (fightOnNow) splitFight++
                    remaining = without
                }
            }
            if (DEBUG_LOG && detachedIds.size != detachedBefore)
                println("detach t=$now: ${detachedIds.size} detached (was $detachedBefore) farmer=$farmer dryHunt=$dryHunt race=$raceNow targets=$raceTargets(${racePaired.size} paired) largest=$largestGroup/${armedEnemies.size} dry=${now - lastDistanceKeptTick} hurt=${now - lastHurtTick} fire=${now - lastFireTick} reach=${now - lastReachTick} contact=$contact theirs=${theirs.toInt()}")
        } else detachedIds.clear()
        val interceptDenies = interceptFlag != null && !interceptFlag.ours
        // ЗАЧИСТКА ФЛАГОВ ВМЕСТО ПОГОНИ (v124, стенд blitz m28 на v122, 3961:23980): позади по очкам против врага, который не
        // дерётся, армия 200 тиков (42–239) толкала его пятёрку в 647 мощи при своих 3575 — та уходит в шести на той же
        // скорости, — пока его одиночные хранители держали шесть флагов; флаг под одним-двумя его крипами армия берёт, а
        // группу не догоняет. Есть цель-флаг, проходящая гейт стаи, — погоня снята, как при перехвате
        // ...и не по ярлыку «не дерётся» (он гаснет, пока его хранители мелькают в досягаемости), а по сухости самой погони: ни
        // нашего выстрела, ни удара по нам PASSIVE_TICKS подряд (blitz m28: с 83-го по 239-й ни того ни другого при ANNIHILATE)
        // страховка CPU на постуре (v131c): тик уже дороже CPU_GUARD_MS — цель-флаг оценивается только текущая, потоки выхода не
        // пересчитываются; тёплые тики (6–9 мс на стенде) сюда не доходят
        val cpuGuardArmy = USE_CPU_GUARD && now > 1 && cpuMs() > CPU_GUARD_MS
        if (cpuGuardArmy && DEBUG_LOG) println("cpu t=$now guard: posture keeps the objective (${(cpuMs() * 10).toInt() / 10.0}ms)")
        val dryNow = (lastFireTick < 0 || now - lastFireTick >= PASSIVE_TICKS) && now - lastHurtTick >= PASSIVE_TICKS
        val sweepObjective: FlagInfo? = null   // USE_SWEEP_OVER_CHASE снят (v214): см. docs
cpuMark("a.sweep")
        val chaseVeto = (enemyNotFightingNow && (interceptDenies || !behindOnScore)) || sweepObjective != null
        // ОТКРЫТАЯ НАХОДКА (матч 70): второй источник мигания — «ловимых нет»: блоб, шагнувший назад на две клетки, делает
        // «уходящими» всех двенадцать на восемь тиков (см. evasive), и наступление снимается на эти тики, армия к посту.
        // Два устранения ОТВЕРГНУТЫ стендом: гистерезис по ловимости (наступление снимается лишь после целого CHASE_WINDOW без
        // ловимых) — 51 хуже / 51 лучше, гейтовые m28 farm+weak и m30 camp красные, кайтеры добиваются позже на десятке карт,
        // m16 kite проигран; порог evasive «больше половины окна» — 66 хуже / 44 лучше. Быстрое снятие наступления, когда
        // ловимых нет, — то, чем армия не гонится за кайтером; цена — эти тики против блоба, который отступает и возвращается
        // отрыв с темпом (v127, USE_LEAD_HOLDS): впереди по счёту и по проекции — толчка и прижима нет, бой только его
        val leadHolds = USE_LEAD_HOLDS && !behindOnScore && ourScore > enemyScore && armedEnemies.isNotEmpty()
        if (DEBUG_LOG && leadHolds != leadHoldsWas) println("lead t=$now: holds ${if (leadHolds) "on" else "off"} score=$ourScore:$enemyScore rate=$ourRate:$enemyRate push=${oursPush.toInt()}:${theirsPush.toInt()}")
        leadHoldsWas = leadHolds
        val pushRaw = !stalled && !leadHolds && (sweep || (exchangePaying && !chaseVeto && huntable.isNotEmpty() && strikers.isNotEmpty() && oursPush >= theirsPush * (if (pushing) pushRelease else pushRatio)))
        // ...и СРОК (v215, см. USE_PUSH_DWELL): начатое наступление живёт минимум PUSH_DWELL тиков, и снимают его
        // досрочно только затор и настоящая слабость — мощь ниже порога отпускания. Мигание любого из пяти прочих
        // множителей за этот срок армию не разворачивает.
        // ...ТОЛЬКО В ИДУЩЕМ БОЮ, и это не осторожность, а замер: без оговорки строка match28:scatter перестала
        // проходить гейт, а отрыв упал на 40 509. Причина по существу записана соседним комментарием: быстрое
        // снятие наступления, когда ловимых нет, — это ровно то, чем армия не гонится за кайтером и за рассыпавшимся
        // фермером. Разворот, на который жалуется оператор, случается В БОЮ; вне боя мигание `huntable` полезно.
        // ⚠️ Мерились три редакции, и средняя выбрана не по вкусу, а по числам:
        //   без оговорки вовсе — строка match28:scatter НЕ ПРОХОДИТ гейт, отрыв −40 509;
        //   `fightOnNow` (эта) — FAIL нет, отрыв −3 545, 90 строк не тронуты, срок срабатывает на 0,6 % тиков,
        //      смен постуры 5,12 -> 4,74 на сто тиков, и все пять «потерянных» уничтожений стали крупными
        //      победами по очкам (match31:camp: уничтожение при ПРОИГРЫШЕ 4 391:6 400 -> отрыв 23 245:18 056);
        //   `meleeAdjacent` (его мили вплотную) — стенд ровный (134 строки без изменений), но срок срабатывает
        //      ОДИН раз на 125 110 тиков. Это не осторожная редакция, а мёртвый код, и потому отвергнута.
        // Живое основание сильнее стендового: из 1 189 быстрых смен постуры в рейтинговой серии 852 несут смену
        // `pushing`, а стенд в режим боя почти не входит (cmdwhy fight:8 из 570 тиков). Судит живая серия
        pushHeld = false
        // ...и РАЗМЕН НИЖЕ ПАРИТЕТА ГАСИТ НАСТУПЛЕНИЕ (v217, см. USE_BREAK_OFF_HOLDS_LINE), а не разворачивает
        // армию: толчка вперёд нет, строй и лекари остаются
        // ...и БЕЗ СВОЕГО pushTicks++ (v218, дефект прибора): счётчик увеличивается безусловно десятью строками
        // ниже, поэтому на тиках размена он рос ДВАЖДЫ — и `pushheld` занижался ровно на тех тиках, ради которых
        // прибор и ставился
        if (USE_BREAK_OFF_HOLDS_LINE && breakOffNow) { pushing = false } else
        pushing = if (!USE_PUSH_DWELL) pushRaw else when {
            pushRaw -> { if (!pushing) pushSince = now; true }
            pushing && fightOnNow && now - pushSince < PUSH_DWELL && !stalled && oursPush >= theirsPush * pushRelease -> {
                pushHeld = true; pushHeldTicks++; true
            }
            else -> false
        }
        pushTicks++
        // бой по контакту — пока отход невозможен: мили врага вплотную. Решение ТИК ЗА ТИКОМ, и это не дрожание, а
        // кайт погони: слабее — отходим, стреляя и рубя на ходу (strike/shoot идут в любой постуре); догнал мили —
        // вся армия разворачивается на него (авангард погони один против всех), отстал — снова отход. На стенде
        // sleeper при 0.83 это 10:0; «поймали — деремся до конца контакта» дало 2:11, «слабее — только отход» 2:6
        // ...И КОНТАКТ БЕЗ РАЗМЕНА ХИТОВ С ИДУЩИМ ВРАГОМ — НЕ БОЙ (v221, см. USE_FIGHT_BY_LEDGER): стояние в трёх–пяти
        // клетках от его тычущей линии, за окно которого ни одна сторона не потеряла STALL_DAMAGE, держало армию без
        // флаг-цели 35 % проигранных забегов. Бой, как и прежде: его мили вплотную, загнанная неподвижная группа
        // (cornered) и — см. USE_WARM_NEEDS_HIS_MOVE — любой СТОЯЩИЙ враг в контакте: стоящего атакуем мы
        // `warmNow` считается здесь один раз и читается постурой, линией и приборами — одна величина на всех
        val hisStill = hisCentHist.size >= 2 && run {
